INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-1-03', 'ngsl-1', 'Thông dụng 1–500 · Bộ 3', 'New General Service List, thứ hạng 1–500', '#3da9fc', 'BookOpen', 3);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 1, 'help', 'giúp; giúp đỡ', 'verb', '[{"en":"My older brother helped me with my math homework.","vi":"Anh trai tôi đã giúp tôi làm bài tập toán."},{"en":"Neighbors should help each other in difficult times.","vi":"Hàng xóm nên giúp đỡ nhau những lúc khó khăn."},{"en":"A short walk after dinner helps me sleep better.","vi":"Đi bộ một chút sau bữa tối giúp tôi ngủ ngon hơn."}]', '[{"phrase":"help each other"},{"phrase":"help with homework"},{"phrase":"help a lot"}]', NULL, '/help/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hel/help_/help__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 2, 'ask', 'hỏi; yêu cầu; xin', 'verb', '[{"en":"Can I ask a question about tomorrow''s test?","vi":"Tôi có thể hỏi một câu về bài kiểm tra ngày mai không?"},{"en":"The teacher asked us to turn off our phones.","vi":"Cô giáo yêu cầu chúng tôi tắt điện thoại."},{"en":"She asked her boss for a day off next week.","vi":"Cô ấy xin sếp cho nghỉ một ngày vào tuần sau."}]', '[{"phrase":"ask a question"},{"phrase":"ask for help"},{"phrase":"ask for advice"}]', NULL, '/æsk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ask/ask__/ask__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 3, 'meet', 'gặp; gặp gỡ; làm quen', 'verb', '[{"en":"Let''s meet for coffee after work tomorrow.","vi":"Ngày mai tan làm chúng ta gặp nhau uống cà phê nhé."},{"en":"I met my wife when we were at university.","vi":"Tôi quen vợ mình khi chúng tôi còn học đại học."},{"en":"It was really nice to meet your parents last night.","vi":"Tối qua được gặp bố mẹ bạn thật là vui."}]', '[{"phrase":"meet a friend"},{"phrase":"nice to meet you"},{"phrase":"meet for coffee"}]', 'meet – met – met', '/miːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mee/meet_/meet__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 4, 'start', 'bắt đầu; khởi động', 'verb', '[{"en":"The movie starts at eight, so don''t be late.","vi":"Phim bắt đầu lúc tám giờ, nên đừng đến muộn."},{"en":"She started a new job last month.","vi":"Cô ấy bắt đầu công việc mới vào tháng trước."},{"en":"My old car wouldn''t start this morning.","vi":"Sáng nay chiếc xe cũ của tôi không khởi động được."}]', '[{"phrase":"start a new job"},{"phrase":"start a business"},{"phrase":"start work"}]', NULL, '/stɑːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/start/start__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 5, 'talk', 'nói chuyện; trò chuyện; bàn bạc', 'verb', '[{"en":"We talked on the phone for almost an hour.","vi":"Chúng tôi nói chuyện điện thoại gần một tiếng."},{"en":"Can I talk to you about something important?","vi":"Mình nói chuyện với bạn về một việc quan trọng được không?"},{"en":"My parents never talk about money in front of us.","vi":"Bố mẹ tôi không bao giờ bàn chuyện tiền bạc trước mặt chúng tôi."}]', '[{"phrase":"talk about"},{"phrase":"talk to"},{"phrase":"talk on the phone"}]', NULL, '/tɔːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tal/talk_/talk__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 6, 'something', 'cái gì đó; điều gì đó; chuyện gì đó', 'pronoun', '[{"en":"I have something important to tell you after class.","vi":"Tôi có chuyện quan trọng muốn nói với bạn sau giờ học."},{"en":"Would you like something to drink while you wait?","vi":"Bạn có muốn uống gì trong lúc chờ không?"},{"en":"There''s something wrong with my laptop again.","vi":"Máy tính xách tay của tôi lại có vấn đề gì đó rồi."}]', '[{"phrase":"something else"},{"phrase":"something to drink"},{"phrase":"something wrong"}]', NULL, '/ˈsʌmθɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/somet/something__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 7, 'put', 'đặt; để; cho vào', 'verb', '[{"en":"Please put the milk back in the fridge.","vi":"Làm ơn để sữa lại vào tủ lạnh."},{"en":"Did you put sugar in my coffee?","vi":"Bạn có cho đường vào cà phê của tôi không?"},{"en":"He put down his bag and sat on the sofa.","vi":"Anh ấy đặt túi xuống rồi ngồi lên ghế sofa."}]', '[{"phrase":"put back"},{"phrase":"put down"},{"phrase":"put away"}]', 'put – put – put', '/pʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/put/put__/put__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 8, 'another', 'một… khác; thêm một', 'determiner', '[{"en":"Could I have another cup of tea, please?","vi":"Cho tôi thêm một tách trà nữa được không?"},{"en":"Do you have this shirt in another color?","vi":"Bạn có chiếc áo này màu khác không?"},{"en":"I''m busy now, so let''s talk about it another time.","vi":"Giờ tôi đang bận, để lúc khác chúng ta nói chuyện nhé."}]', '[{"phrase":"another time"},{"phrase":"another day"},{"phrase":"one another"}]', NULL, '/əˈnʌðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ano/anoth/another__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 9, 'become', 'trở thành; trở nên', 'verb', '[{"en":"She wants to become a doctor like her mother.","vi":"Cô ấy muốn trở thành bác sĩ giống mẹ mình."},{"en":"The weather became colder after the sun went down.","vi":"Trời trở nên lạnh hơn sau khi mặt trời lặn."},{"en":"They became good friends during their first year at college.","vi":"Họ trở thành bạn thân trong năm đầu đại học."}]', '[{"phrase":"become friends"},{"phrase":"become popular"},{"phrase":"become clear"}]', 'become – became – become', '/bɪˈkʌm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bec/becom/become__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 10, 'interest', 'sự quan tâm; hứng thú; sở thích', 'noun', '[{"en":"My son has shown a lot of interest in music lately.","vi":"Gần đây con trai tôi tỏ ra rất quan tâm đến âm nhạc."},{"en":"Reading and cooking are my main interests.","vi":"Đọc sách và nấu ăn là những sở thích chính của tôi."},{"en":"She lost interest in the game after a few minutes.","vi":"Cô bé mất hứng thú với trò chơi chỉ sau vài phút."}]', '[{"phrase":"interest in"},{"phrase":"show interest"},{"phrase":"lose interest"}]', 'interest in something', '/ˈɪntrəst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interest__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 11, 'country', 'đất nước; quốc gia; vùng quê', 'noun', '[{"en":"Have you ever lived in a foreign country?","vi":"Bạn đã bao giờ sống ở nước ngoài chưa?"},{"en":"Vietnam is a country with beautiful beaches and friendly people.","vi":"Việt Nam là một đất nước có những bãi biển đẹp và người dân thân thiện."},{"en":"My grandparents moved to the country after they retired.","vi":"Ông bà tôi chuyển về vùng quê sau khi nghỉ hưu."}]', '[{"phrase":"foreign country"},{"phrase":"all over the country"},{"phrase":"developing country"}]', NULL, '/ˈkʌntri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/count/country__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 12, 'old', 'già; cũ; (bao nhiêu) tuổi', 'adjective', '[{"en":"My grandfather is old, but he still walks every day.","vi":"Ông tôi đã già nhưng vẫn đi bộ mỗi ngày."},{"en":"I gave my old clothes to my younger cousin.","vi":"Tôi đã cho em họ quần áo cũ của mình."},{"en":"How old was your daughter when she started school?","vi":"Con gái bạn bao nhiêu tuổi khi bắt đầu đi học?"}]', '[{"phrase":"old friend"},{"phrase":"years old"},{"phrase":"old clothes"}]', NULL, '/əʊld/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/old/old__/old__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 13, 'school', 'trường học; việc học', 'noun', '[{"en":"After school, the children usually play in the park.","vi":"Sau giờ học, bọn trẻ thường chơi ở công viên."},{"en":"Our school has a big library and a swimming pool.","vi":"Trường chúng tôi có một thư viện lớn và một hồ bơi."},{"en":"She left school at sixteen to help her parents.","vi":"Cô ấy nghỉ học năm mười sáu tuổi để phụ giúp bố mẹ."}]', '[{"phrase":"after school"},{"phrase":"go to school"},{"phrase":"high school"}]', NULL, '/skuːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sch/schoo/school__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 14, 'late', 'muộn; trễ; cuối (giai đoạn)', 'adjective', '[{"en":"I was late for work because my bus broke down.","vi":"Tôi đi làm muộn vì xe buýt bị hỏng."},{"en":"It''s too late to call her now.","vi":"Giờ đã quá muộn để gọi cho cô ấy."},{"en":"We usually go for a walk in the late afternoon.","vi":"Chúng tôi thường đi dạo vào cuối buổi chiều."}]', '[{"phrase":"late for work"},{"phrase":"too late"},{"phrase":"late afternoon"}]', NULL, '/leɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lat/late_/late__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 15, 'high', 'cao', 'adjective', '[{"en":"The wall around the garden is too high to climb.","vi":"Bức tường quanh khu vườn cao quá, không trèo qua được."},{"en":"Prices in the city center are very high.","vi":"Giá cả ở trung tâm thành phố rất cao."},{"en":"She has a high fever, so she''s staying home today.","vi":"Cô bé bị sốt cao nên hôm nay ở nhà."}]', '[{"phrase":"high prices"},{"phrase":"high fever"},{"phrase":"high quality"}]', 'người cao dùng tall, không dùng high', '/haɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hig/high_/high__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 16, 'different', 'khác; khác nhau', 'adjective', '[{"en":"My sister and I look very different.","vi":"Tôi và chị gái trông rất khác nhau."},{"en":"This phone is different from the one I ordered.","vi":"Chiếc điện thoại này khác với cái tôi đã đặt."},{"en":"We tried three different restaurants during our trip.","vi":"Chúng tôi đã thử ba nhà hàng khác nhau trong chuyến đi."}]', '[{"phrase":"different from"},{"phrase":"very different"},{"phrase":"completely different"}]', 'different from', '/ˈdɪfrənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dif/diffe/different__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 17, 'next', 'tiếp theo; sau; bên cạnh', 'adjective', '[{"en":"The next train to the airport leaves in ten minutes.","vi":"Chuyến tàu tiếp theo ra sân bay sẽ chạy sau mười phút nữa."},{"en":"We''re going on vacation with my parents next month.","vi":"Tháng sau chúng tôi sẽ đi nghỉ cùng bố mẹ tôi."},{"en":"The people in the next room were very noisy last night.","vi":"Tối qua những người ở phòng bên cạnh rất ồn ào."}]', '[{"phrase":"next week"},{"phrase":"next time"},{"phrase":"next month"}]', NULL, '/nekst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nex/next_/next__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 18, 'end', 'phần cuối; kết thúc; đầu (mút)', 'noun', '[{"en":"We''ll pay you at the end of the month.","vi":"Chúng tôi sẽ trả tiền cho bạn vào cuối tháng."},{"en":"I didn''t like the end of the movie.","vi":"Tôi không thích đoạn kết của bộ phim."},{"en":"Can you hold the other end of the rope?","vi":"Bạn giữ đầu kia của sợi dây giúp tôi được không?"}]', '[{"phrase":"at the end of"},{"phrase":"in the end"},{"phrase":"come to an end"}]', NULL, '/end/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/end/end__/end__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 19, 'live', 'sống; ở', 'verb', '[{"en":"My grandmother lives alone in a small village.","vi":"Bà tôi sống một mình ở một ngôi làng nhỏ."},{"en":"Where did you live before you moved here?","vi":"Trước khi chuyển đến đây bạn sống ở đâu?"},{"en":"Most pet cats live for about fifteen years.","vi":"Phần lớn mèo nuôi sống được khoảng mười lăm năm."}]', '[{"phrase":"live alone"},{"phrase":"live with"},{"phrase":"live together"}]', NULL, '/lɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/liv/live_/live__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 20, 'while', 'trong khi; trong lúc; còn', 'conjunction', '[{"en":"Someone called while you were in the shower.","vi":"Có người gọi điện trong lúc bạn đang tắm."},{"en":"Please don''t use your phone while driving.","vi":"Làm ơn đừng dùng điện thoại khi đang lái xe."},{"en":"My brother loves sports, while I prefer reading.","vi":"Anh trai tôi mê thể thao, còn tôi thích đọc sách hơn."}]', '[{"phrase":"while driving"},{"phrase":"for a while"},{"phrase":"a while ago"}]', 'a while (danh từ) = một lúc, một thời gian', '/waɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whi/while/while__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 21, 'world', 'thế giới', 'noun', '[{"en":"She dreams of traveling around the world one day.","vi":"Cô ấy mơ một ngày nào đó được đi du lịch vòng quanh thế giới."},{"en":"This is the best pizza in the world!","vi":"Đây là chiếc pizza ngon nhất thế giới!"},{"en":"English is spoken in many parts of the world.","vi":"Tiếng Anh được nói ở nhiều nơi trên thế giới."}]', '[{"phrase":"around the world"},{"phrase":"in the world"},{"phrase":"all over the world"}]', NULL, '/wɜːrld/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wor/world/world__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 22, 'week', 'tuần', 'noun', '[{"en":"I go to the gym three times a week.","vi":"Tôi đi tập gym ba lần một tuần."},{"en":"We''re moving to a new apartment next week.","vi":"Tuần sau chúng tôi chuyển đến căn hộ mới."},{"en":"She spent a week at the beach with her friends.","vi":"Cô ấy đã dành một tuần ở biển cùng bạn bè."}]', '[{"phrase":"next week"},{"phrase":"last week"},{"phrase":"every week"}]', NULL, '/wiːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wee/week_/week__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 23, 'play', 'chơi; thi đấu; đóng vai', 'verb', '[{"en":"The kids are playing games in the garden.","vi":"Bọn trẻ đang chơi trò chơi trong vườn."},{"en":"We''re playing against the best team in the city tomorrow.","vi":"Ngày mai chúng tôi thi đấu với đội mạnh nhất thành phố."},{"en":"He played a doctor in his first movie.","vi":"Anh ấy đóng vai bác sĩ trong bộ phim đầu tiên của mình."}]', '[{"phrase":"play games"},{"phrase":"play against"},{"phrase":"play a role"},{"phrase":"play the guitar"}]', NULL, '/pleɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/play_/play__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 24, 'home', 'nhà; tổ ấm; quê nhà', 'noun', '[{"en":"After a long day, it''s nice to be at home.","vi":"Sau một ngày dài, được ở nhà thật dễ chịu."},{"en":"They''re building a new home near the lake.","vi":"Họ đang xây một ngôi nhà mới gần hồ."},{"en":"This city has been my home for ten years.","vi":"Thành phố này đã là nhà của tôi suốt mười năm nay."}]', '[{"phrase":"at home"},{"phrase":"go home"},{"phrase":"leave home"},{"phrase":"feel at home"}]', 'go home (không nói "go to home")', '/həʊm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hom/home_/home__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 25, 'never', 'không bao giờ; chưa bao giờ', 'adverb', '[{"en":"I''ve never been on a plane before.","vi":"Tôi chưa bao giờ đi máy bay."},{"en":"She never drinks coffee in the afternoon because it keeps her awake.","vi":"Cô ấy không bao giờ uống cà phê vào buổi chiều vì sẽ bị mất ngủ."},{"en":"I''ll never forget the day my son was born.","vi":"Tôi sẽ không bao giờ quên ngày con trai tôi chào đời."}]', '[{"phrase":"never forget"},{"phrase":"never mind"},{"phrase":"almost never"}]', NULL, '/ˈnevər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nev/never/never__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 26, 'include', 'bao gồm; tính cả; đưa vào', 'verb', '[{"en":"Does the room price include breakfast and free parking?","vi":"Giá phòng có bao gồm bữa sáng và chỗ đậu xe miễn phí không?"},{"en":"There were twelve people at dinner, including the kids.","vi":"Có mười hai người ăn tối, tính cả bọn trẻ."},{"en":"Please include your phone number in the email.","vi":"Vui lòng ghi kèm số điện thoại của bạn trong email."}]', '[{"phrase":"price includes"},{"phrase":"include information"},{"phrase":"including tax"}]', NULL, '/ɪnˈkluːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/inclu/include__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 27, 'course', 'khóa học; món ăn', 'noun', '[{"en":"I''m taking an online course in cooking this summer.","vi":"Mùa hè này tôi đang học một khóa nấu ăn trực tuyến."},{"en":"For the main course, I''ll have the chicken.","vi":"Món chính thì tôi sẽ gọi món gà."},{"en":"She passed the course with very high marks.","vi":"Cô ấy đã hoàn thành khóa học với điểm rất cao."}]', '[{"phrase":"take a course"},{"phrase":"online course"},{"phrase":"main course"}]', 'of course = tất nhiên', '/kɔːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/cours/course__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 28, 'house', 'ngôi nhà; nhà', 'noun', '[{"en":"They bought a small house with a garden.","vi":"Họ đã mua một ngôi nhà nhỏ có vườn."},{"en":"Let''s have the party at my house on Saturday.","vi":"Thứ Bảy mình tổ chức bữa tiệc ở nhà mình nhé."},{"en":"We need to clean the whole house before the guests arrive.","vi":"Chúng tôi cần dọn dẹp cả nhà trước khi khách đến."}]', '[{"phrase":"buy a house"},{"phrase":"clean the house"},{"phrase":"at my house"}]', 'house (ngôi nhà) ≠ home (nơi mình sống, tổ ấm)', '/haʊs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hou/house/house__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 29, 'report', 'bản báo cáo; bản tin', 'noun', '[{"en":"I have to finish this report before Friday.","vi":"Tôi phải hoàn thành bản báo cáo này trước thứ Sáu."},{"en":"According to the weather report, it will rain tomorrow.","vi":"Theo bản tin thời tiết, ngày mai trời sẽ mưa."},{"en":"The manager asked me to write a short report on the meeting.","vi":"Quản lý yêu cầu tôi viết một bản báo cáo ngắn về cuộc họp."}]', '[{"phrase":"write a report"},{"phrase":"weather report"},{"phrase":"news report"},{"phrase":"annual report"}]', NULL, '/rɪˈpɔːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repor/report__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-03', 30, 'group', 'nhóm', 'noun', '[{"en":"We studied in small groups for the exam.","vi":"Chúng tôi học theo nhóm nhỏ để ôn thi."},{"en":"A group of tourists was taking photos outside the museum.","vi":"Một nhóm khách du lịch đang chụp ảnh bên ngoài bảo tàng."},{"en":"Children in this age group need about ten hours of sleep.","vi":"Trẻ em ở nhóm tuổi này cần ngủ khoảng mười tiếng."}]', '[{"phrase":"a group of"},{"phrase":"small group"},{"phrase":"age group"}]', NULL, '/ɡruːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gro/group/group__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-1-04', 'ngsl-1', 'Thông dụng 1–500 · Bộ 4', 'New General Service List, thứ hạng 1–500', '#3da9fc', 'BookOpen', 4);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 1, 'case', 'trường hợp; vụ án; hộp, vỏ đựng', 'noun', '[{"en":"In that case, we should leave a little earlier.","vi":"Trong trường hợp đó, chúng ta nên đi sớm hơn một chút."},{"en":"The police are still working on the case.","vi":"Cảnh sát vẫn đang điều tra vụ án."},{"en":"I bought a new case for my phone yesterday.","vi":"Hôm qua tôi đã mua một cái vỏ mới cho điện thoại."}]', '[{"phrase":"in that case"},{"phrase":"in any case"},{"phrase":"just in case"},{"phrase":"phone case"}]', NULL, '/keɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cas/case_/case__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 2, 'woman', 'phụ nữ; người đàn bà', 'noun', '[{"en":"The woman at the front desk gave us our room keys.","vi":"Người phụ nữ ở quầy lễ tân đưa chìa khóa phòng cho chúng tôi."},{"en":"Many women in my office work from home on Fridays.","vi":"Nhiều phụ nữ trong văn phòng tôi làm việc ở nhà vào thứ Sáu."},{"en":"She grew up to be a strong and kind woman.","vi":"Cô ấy lớn lên thành một người phụ nữ mạnh mẽ và tốt bụng."}]', '[{"phrase":"young woman"},{"phrase":"old woman"},{"phrase":"married woman"}]', 'số nhiều: women', '/ˈwʊmən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wom/woman/woman__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 3, 'around', 'xung quanh; khắp; khoảng', 'preposition', '[{"en":"We sat around the table and talked all evening.","vi":"Chúng tôi ngồi quanh bàn và trò chuyện suốt buổi tối."},{"en":"She has traveled around the world twice.","vi":"Cô ấy đã đi vòng quanh thế giới hai lần."},{"en":"I''ll meet you at around seven o''clock.","vi":"Tôi sẽ gặp bạn vào khoảng bảy giờ."}]', '[{"phrase":"around the world"},{"phrase":"around the corner"},{"phrase":"look around"},{"phrase":"turn around"}]', NULL, '/əˈraʊnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aro/aroun/around__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 4, 'book', 'sách; cuốn sách', 'noun', '[{"en":"I''m reading a really good book about the ocean.","vi":"Tôi đang đọc một cuốn sách rất hay về đại dương."},{"en":"My son borrowed three books from the school library.","vi":"Con trai tôi mượn ba cuốn sách từ thư viện trường."},{"en":"She wrote her first book when she was twenty-five.","vi":"Cô ấy viết cuốn sách đầu tiên khi hai mươi lăm tuổi."}]', '[{"phrase":"read a book"},{"phrase":"write a book"},{"phrase":"borrow a book"}]', '(v) book: đặt chỗ, đặt vé', '/bʊk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/boo/book_/book__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 5, 'family', 'gia đình; họ hàng', 'noun', '[{"en":"My family usually has dinner together on Sundays.","vi":"Gia đình tôi thường ăn tối cùng nhau vào Chủ nhật."},{"en":"He moved to the city to support his family.","vi":"Anh ấy chuyển lên thành phố để nuôi gia đình."},{"en":"We have family in both Canada and Australia.","vi":"Chúng tôi có họ hàng ở cả Canada và Úc."}]', '[{"phrase":"family member"},{"phrase":"support a family"},{"phrase":"start a family"}]', NULL, '/ˈfæməli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fam/famil/family__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 6, 'seem', 'có vẻ; dường như', 'verb', '[{"en":"You seem a little tired after your long trip.","vi":"Bạn có vẻ hơi mệt sau chuyến đi dài."},{"en":"It seems that nobody knows the answer to this question.","vi":"Dường như không ai biết câu trả lời cho câu hỏi này."},{"en":"The new manager seems very friendly and easy to talk to.","vi":"Người quản lý mới có vẻ rất thân thiện và dễ nói chuyện."}]', '[{"phrase":"seem to be"},{"phrase":"it seems that"},{"phrase":"seem strange"}]', NULL, '/siːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/see/seem_/seem__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 7, 'let', 'để; cho phép', 'verb', '[{"en":"My parents let me stay up late on weekends.","vi":"Bố mẹ cho phép tôi thức khuya vào cuối tuần."},{"en":"Let me help you carry those heavy bags.","vi":"Để tôi giúp bạn mang mấy cái túi nặng đó."},{"en":"Let''s go for a walk after lunch.","vi":"Chúng ta đi dạo sau bữa trưa nhé."}]', '[{"phrase":"let me know"},{"phrase":"let go"},{"phrase":"let someone in"}]', 'let – let – let; let + người + V nguyên mẫu', '/let/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/let/let__/let__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 8, 'again', 'lại; lần nữa', 'adverb', '[{"en":"Sorry, could you say that again a bit more slowly?","vi":"Xin lỗi, bạn có thể nói lại chậm hơn một chút được không?"},{"en":"I hope we can meet again next year.","vi":"Tôi hy vọng năm sau chúng ta có thể gặp lại nhau."},{"en":"He failed his driving test, so he''s taking it again next month.","vi":"Anh ấy trượt bài thi lái xe nên tháng sau sẽ thi lại lần nữa."}]', '[{"phrase":"once again"},{"phrase":"try again"},{"phrase":"never again"}]', NULL, '/əˈɡen/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aga/again/again__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 9, 'kind', 'loại; kiểu', 'noun', '[{"en":"What kind of music do you like?","vi":"Bạn thích thể loại nhạc nào?"},{"en":"This kind of tree grows well in hot weather.","vi":"Loại cây này phát triển tốt khi thời tiết nóng."},{"en":"The market sells all kinds of fresh fruit.","vi":"Khu chợ bán đủ loại trái cây tươi."}]', '[{"phrase":"all kinds of"},{"phrase":"what kind of"},{"phrase":"this kind of"}]', '(adj) kind: tốt bụng, tử tế', '/kaɪnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kin/kind_/kind__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 10, 'keep', 'giữ; tiếp tục', 'verb', '[{"en":"You can keep the book because I don''t need it anymore.","vi":"Bạn cứ giữ cuốn sách vì tôi không cần nó nữa."},{"en":"Keep walking until you see the post office.","vi":"Cứ đi tiếp cho đến khi bạn thấy bưu điện."},{"en":"Wear a hat to keep warm in the winter.","vi":"Hãy đội mũ để giữ ấm vào mùa đông."}]', '[{"phrase":"keep a secret"},{"phrase":"keep warm"},{"phrase":"keep going"},{"phrase":"keep in touch"}]', 'keep – kept – kept; keep + V-ing: cứ tiếp tục làm gì', '/kiːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kee/keep_/keep__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 11, 'hear', 'nghe (thấy); nghe nói', 'verb', '[{"en":"Can you hear me at the back of the room?","vi":"Bạn ở cuối phòng có nghe thấy tôi không?"},{"en":"I heard a strange noise outside last night.","vi":"Tối qua tôi nghe thấy một tiếng động lạ bên ngoài."},{"en":"Have you heard about the new café near the station?","vi":"Bạn đã nghe nói về quán cà phê mới gần nhà ga chưa?"}]', '[{"phrase":"hear a noise"},{"phrase":"hear about"},{"phrase":"hear from"},{"phrase":"hear the news"}]', 'hear – heard – heard', '/hɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/hear_/hear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 12, 'system', 'hệ thống; chế độ', 'noun', '[{"en":"Our office is installing a new computer system next week.","vi":"Tuần tới văn phòng chúng tôi sẽ lắp đặt hệ thống máy tính mới."},{"en":"The city has a cheap and reliable public transportation system.","vi":"Thành phố có hệ thống giao thông công cộng rẻ và đáng tin cậy."},{"en":"The education system in this country is changing quickly.","vi":"Hệ thống giáo dục ở nước này đang thay đổi nhanh chóng."}]', '[{"phrase":"computer system"},{"phrase":"education system"},{"phrase":"operating system"}]', NULL, '/ˈsɪstəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sys/syste/system__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 13, 'question', 'câu hỏi; vấn đề', 'noun', '[{"en":"Can I ask you a question about the homework?","vi":"Cho tôi hỏi bạn một câu về bài tập về nhà được không?"},{"en":"She answered every question on the test correctly.","vi":"Cô ấy trả lời đúng mọi câu hỏi trong bài kiểm tra."},{"en":"The real question is whether we have enough money.","vi":"Vấn đề thật sự là liệu chúng ta có đủ tiền hay không."}]', '[{"phrase":"ask a question"},{"phrase":"answer a question"},{"phrase":"good question"}]', NULL, '/ˈkwestʃən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/que/quest/question__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 14, 'during', 'trong (suốt); trong lúc', 'preposition', '[{"en":"Please turn off your phone during the movie.","vi":"Vui lòng tắt điện thoại trong suốt buổi chiếu phim."},{"en":"I worked at a café during summer vacation.","vi":"Tôi làm việc ở một quán cà phê trong kỳ nghỉ hè."},{"en":"Did anyone call during my meeting this afternoon?","vi":"Có ai gọi trong lúc tôi họp chiều nay không?"}]', '[{"phrase":"during the day"},{"phrase":"during the night"},{"phrase":"during the week"}]', 'during + danh từ ≠ while + mệnh đề', '/ˈdʊrɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dur/durin/during__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 15, 'always', 'luôn luôn; lúc nào cũng', 'adverb', '[{"en":"She always drinks a cup of coffee before work.","vi":"Cô ấy luôn uống một tách cà phê trước khi đi làm."},{"en":"My grandmother is always happy to see us.","vi":"Bà tôi lúc nào cũng vui khi gặp chúng tôi."},{"en":"I have always wanted to learn how to play the piano.","vi":"Tôi luôn muốn học chơi đàn piano."}]', '[{"phrase":"almost always"},{"phrase":"not always"},{"phrase":"always remember"}]', NULL, '/ˈɔːlweɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alw/alway/always__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 16, 'big', 'to, lớn; quan trọng', 'adjective', '[{"en":"They live in a big house near the river.","vi":"Họ sống trong một ngôi nhà lớn gần con sông."},{"en":"These shoes are a little too big for my son.","vi":"Đôi giày này hơi to so với con trai tôi."},{"en":"Tomorrow is a big day for our whole team.","vi":"Ngày mai là một ngày quan trọng với cả đội chúng tôi."}]', '[{"phrase":"big city"},{"phrase":"big problem"},{"phrase":"big day"},{"phrase":"big deal"}]', NULL, '/bɪɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/big/big__/big__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 17, 'set', 'đặt; đặt ra; (mặt trời) lặn', 'verb', '[{"en":"She set the plates on the table before dinner.","vi":"Cô ấy đặt đĩa lên bàn trước bữa tối."},{"en":"Our team has set a clear goal for next year.","vi":"Đội chúng tôi đã đặt ra một mục tiêu rõ ràng cho năm tới."},{"en":"We sat on the beach and watched the sun set.","vi":"Chúng tôi ngồi trên bãi biển và ngắm mặt trời lặn."}]', '[{"phrase":"set a goal"},{"phrase":"set an alarm"},{"phrase":"set the table"},{"phrase":"set a record"}]', 'set – set – set', '/set/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/set/set__/set__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 18, 'small', 'nhỏ, bé', 'adjective', '[{"en":"We rented a small apartment close to the city center.","vi":"Chúng tôi thuê một căn hộ nhỏ gần trung tâm thành phố."},{"en":"Could I have a small coffee with milk, please?","vi":"Cho tôi một ly cà phê sữa cỡ nhỏ nhé."},{"en":"She grew up in a small town in the mountains.","vi":"Cô ấy lớn lên ở một thị trấn nhỏ trên núi."}]', '[{"phrase":"small town"},{"phrase":"small business"},{"phrase":"small amount"},{"phrase":"small group"}]', NULL, '/smɔːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sma/small/small__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 19, 'study', 'học; nghiên cứu', 'verb', '[{"en":"My older sister is studying to become a doctor.","vi":"Chị gái tôi đang học để trở thành bác sĩ."},{"en":"I need to study for my English exam tonight.","vi":"Tối nay tôi cần học để thi môn tiếng Anh."},{"en":"Scientists have studied these birds for many years.","vi":"Các nhà khoa học đã nghiên cứu những loài chim này trong nhiều năm."}]', '[{"phrase":"study hard"},{"phrase":"study for an exam"},{"phrase":"study abroad"}]', NULL, '/ˈstʌdi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/stu/study/study__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 20, 'follow', 'đi theo; làm theo; theo dõi', 'verb', '[{"en":"Follow me, and I''ll show you to your seat.","vi":"Đi theo tôi, tôi sẽ dẫn bạn đến chỗ ngồi."},{"en":"Please follow the instructions on the box carefully.","vi":"Vui lòng làm theo hướng dẫn trên hộp một cách cẩn thận."},{"en":"Do you follow any cooking channels on social media?","vi":"Bạn có theo dõi kênh nấu ăn nào trên mạng xã hội không?"}]', '[{"phrase":"follow instructions"},{"phrase":"follow the rules"},{"phrase":"follow advice"}]', NULL, '/ˈfɑːləʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fol/follo/follow__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 21, 'begin', 'bắt đầu', 'verb', '[{"en":"The meeting will begin at nine o''clock sharp.","vi":"Cuộc họp sẽ bắt đầu đúng chín giờ."},{"en":"She began learning English when she was six.","vi":"Cô ấy bắt đầu học tiếng Anh khi lên sáu tuổi."},{"en":"It began to rain just as we left the house.","vi":"Trời bắt đầu mưa đúng lúc chúng tôi ra khỏi nhà."}]', '[{"phrase":"begin with"},{"phrase":"begin work"},{"phrase":"begin again"}]', 'begin – began – begun', '/bɪˈɡɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/beg/begin/begin__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 22, 'important', 'quan trọng', 'adjective', '[{"en":"I have an important meeting with my boss tomorrow.","vi":"Ngày mai tôi có một cuộc họp quan trọng với sếp."},{"en":"It''s important to drink enough water every day.","vi":"Uống đủ nước mỗi ngày là điều quan trọng."},{"en":"Good sleep is just as important as healthy food.","vi":"Giấc ngủ ngon cũng quan trọng như thức ăn lành mạnh."}]', '[{"phrase":"very important"},{"phrase":"important decision"},{"phrase":"important role"}]', NULL, '/ɪmˈpɔːrtnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impor/important__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 23, 'since', 'từ, kể từ (khi); vì', 'conjunction', '[{"en":"We have lived in this house since 2015.","vi":"Chúng tôi đã sống trong ngôi nhà này từ năm 2015."},{"en":"I haven''t seen him since we finished high school.","vi":"Tôi chưa gặp lại anh ấy kể từ khi chúng tôi học xong cấp ba."},{"en":"Since it''s raining, let''s stay home and watch a movie.","vi":"Vì trời đang mưa nên chúng ta ở nhà xem phim đi."}]', '[{"phrase":"ever since"},{"phrase":"since then"}]', 'since + mốc thời gian ≠ for + khoảng thời gian', '/sɪns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sin/since/since__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 24, 'run', 'chạy; điều hành, quản lý', 'verb', '[{"en":"I run in the park every morning before work.","vi":"Tôi chạy bộ trong công viên mỗi sáng trước khi đi làm."},{"en":"We had to run to catch the last bus.","vi":"Chúng tôi phải chạy để kịp chuyến xe buýt cuối cùng."},{"en":"Her parents run a small restaurant in the city center.","vi":"Bố mẹ cô ấy quản lý một nhà hàng nhỏ ở trung tâm thành phố."}]', '[{"phrase":"run a business"},{"phrase":"run away"},{"phrase":"run out of"}]', 'run – ran – run', '/rʌn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/run/run__/run__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 25, 'under', 'dưới; dưới (mức), ít hơn', 'preposition', '[{"en":"The cat is sleeping under the kitchen table.","vi":"Con mèo đang ngủ dưới gầm bàn bếp."},{"en":"Children under five can travel on the train for free.","vi":"Trẻ em dưới năm tuổi được đi tàu miễn phí."},{"en":"I found my keys under a pile of papers.","vi":"Tôi tìm thấy chìa khóa dưới một đống giấy."}]', '[{"phrase":"under the table"},{"phrase":"under pressure"},{"phrase":"under control"}]', NULL, '/ˈʌndər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/under__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 26, 'turn', 'rẽ; quay (lại); chuyển sang, trở nên', 'verb', '[{"en":"Turn left at the next traffic light.","vi":"Rẽ trái ở đèn giao thông tiếp theo."},{"en":"She turned and waved goodbye to us.","vi":"Cô ấy quay lại và vẫy tay chào tạm biệt chúng tôi."},{"en":"The leaves turn red and yellow in the fall.","vi":"Lá cây chuyển sang màu đỏ và vàng vào mùa thu."}]', '[{"phrase":"turn left"},{"phrase":"turn around"},{"phrase":"turn on"},{"phrase":"turn off"}]', NULL, '/tɜːrn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tur/turn_/turn__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 27, 'few', 'một vài; ít', 'determiner', '[{"en":"I''ll be back in a few minutes.","vi":"Tôi sẽ quay lại trong vài phút nữa."},{"en":"We spent a few days at the beach last summer.","vi":"Mùa hè năm ngoái chúng tôi đã ở biển vài ngày."},{"en":"Very few people came to the meeting because of the storm.","vi":"Rất ít người đến buổi họp vì cơn bão."}]', '[{"phrase":"a few"},{"phrase":"very few"},{"phrase":"quite a few"}]', 'a few: một vài ≠ few: rất ít', '/fjuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/few/few__/few__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 28, 'bring', 'mang (đến), đem theo; dẫn theo', 'verb', '[{"en":"Don''t forget to bring your passport to the airport.","vi":"Đừng quên mang theo hộ chiếu ra sân bay."},{"en":"Can I bring a friend to your party?","vi":"Tôi có thể dẫn một người bạn đến bữa tiệc của bạn không?"},{"en":"She brought us some snacks back from her trip.","vi":"Cô ấy mang về cho chúng tôi ít đồ ăn vặt từ chuyến đi."}]', '[{"phrase":"bring back"},{"phrase":"bring a friend"},{"phrase":"bring together"}]', 'bring – brought – brought', '/brɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bri/bring/bring__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 29, 'early', 'sớm; đầu (giai đoạn)', 'adverb', '[{"en":"I usually get up early on weekdays.","vi":"Tôi thường dậy sớm vào các ngày trong tuần."},{"en":"We arrived at the airport two hours early.","vi":"Chúng tôi đến sân bay sớm hai tiếng."},{"en":"This house was built in the early 1900s.","vi":"Ngôi nhà này được xây vào đầu những năm 1900."}]', '[{"phrase":"get up early"},{"phrase":"early morning"},{"phrase":"too early"}]', NULL, '/ˈɜːrli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ear/early/early__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-04', 30, 'hand', 'tay, bàn tay; sự giúp đỡ', 'noun', '[{"en":"Please wash your hands before you sit down to eat.","vi":"Hãy rửa tay trước khi ngồi vào ăn."},{"en":"She was holding a cup of tea in her hand.","vi":"Cô ấy đang cầm một tách trà trong tay."},{"en":"Could you give me a hand with these boxes?","vi":"Bạn có thể giúp tôi một tay với mấy cái thùng này không?"}]', '[{"phrase":"give someone a hand"},{"phrase":"shake hands"},{"phrase":"wash your hands"},{"phrase":"hold hands"}]', NULL, '/hænd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/han/hand_/hand__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-1-05', 'ngsl-1', 'Thông dụng 1–500 · Bộ 5', 'New General Service List, thứ hạng 1–500', '#3da9fc', 'BookOpen', 5);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 1, 'state', 'tình trạng; bang; nhà nước', 'noun', '[{"en":"The old house was in a terrible state when we bought it.","vi":"Căn nhà cũ ở trong tình trạng tồi tệ khi chúng tôi mua nó."},{"en":"She moved to another state to start a new job.","vi":"Cô ấy chuyển đến một bang khác để bắt đầu công việc mới."},{"en":"Most hospitals here are run by the state.","vi":"Hầu hết bệnh viện ở đây do nhà nước điều hành."}]', '[{"phrase":"in a terrible state"},{"phrase":"state of mind"},{"phrase":"state school"}]', NULL, '/steɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/state/state__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 2, 'move', 'di chuyển; chuyển nhà', 'verb', '[{"en":"Could you move your bag? I want to sit down.","vi":"Bạn có thể dời cái túi đi được không? Tôi muốn ngồi xuống."},{"en":"We moved to a bigger apartment last year.","vi":"Năm ngoái chúng tôi đã chuyển đến một căn hộ rộng hơn."},{"en":"The table is too heavy for one person to move.","vi":"Cái bàn quá nặng, một người không thể di chuyển được."}]', '[{"phrase":"move to"},{"phrase":"move house"},{"phrase":"move in"}]', NULL, '/muːv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mov/move_/move__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 3, 'money', 'tiền', 'noun', '[{"en":"I''m trying to save money for a new laptop.","vi":"Tôi đang cố gắng tiết kiệm tiền để mua máy tính xách tay mới."},{"en":"How much money did you spend on the trip?","vi":"Bạn đã tiêu bao nhiêu tiền cho chuyến đi?"},{"en":"He doesn''t earn much money, but he loves his job.","vi":"Anh ấy không kiếm được nhiều tiền nhưng rất yêu công việc của mình."}]', '[{"phrase":"save money"},{"phrase":"spend money"},{"phrase":"earn money"},{"phrase":"make money"}]', 'không đếm được', '/ˈmʌni/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mon/money/money__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 4, 'fact', 'sự thật; thực tế', 'noun', '[{"en":"It''s a fact that exercise is good for your health.","vi":"Tập thể dục tốt cho sức khỏe là một sự thật."},{"en":"In fact, I''ve never been on a plane before.","vi":"Thực ra, tôi chưa bao giờ đi máy bay."},{"en":"I like the fact that my office is close to home.","vi":"Tôi thích việc văn phòng của mình ở gần nhà."}]', '[{"phrase":"in fact"},{"phrase":"the fact that"},{"phrase":"an interesting fact"}]', NULL, '/fækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fac/fact_/fact__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 5, 'however', 'tuy nhiên; dù thế nào', 'adverb', '[{"en":"The hotel was expensive; however, the rooms were very clean.","vi":"Khách sạn khá đắt; tuy nhiên, phòng rất sạch sẽ."},{"en":"The food, however, was not as good as we expected.","vi":"Tuy nhiên, đồ ăn không ngon như chúng tôi mong đợi."},{"en":"However hard I try, I can''t wake up early.","vi":"Dù cố gắng thế nào, tôi cũng không thể dậy sớm."}]', '[{"phrase":"however hard"},{"phrase":"however much"},{"phrase":"however long"}]', NULL, '/haʊˈevər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/how/howev/however__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 6, 'area', 'khu vực; lĩnh vực', 'noun', '[{"en":"There are a lot of good restaurants in this area.","vi":"Có rất nhiều nhà hàng ngon ở khu vực này."},{"en":"They live in a quiet area outside the city.","vi":"Họ sống ở một khu vực yên tĩnh ngoài thành phố."},{"en":"Customer service is an area where we need to improve.","vi":"Dịch vụ khách hàng là lĩnh vực mà chúng tôi cần cải thiện."}]', '[{"phrase":"in the area"},{"phrase":"local area"},{"phrase":"quiet area"}]', NULL, '/ˈeriə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/are/area_/area__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 7, 'provide', 'cung cấp; chu cấp', 'verb', '[{"en":"The hotel provides free breakfast for all guests.","vi":"Khách sạn cung cấp bữa sáng miễn phí cho tất cả khách."},{"en":"Can you provide more information about the job?","vi":"Bạn có thể cung cấp thêm thông tin về công việc không?"},{"en":"Parents provide their children with food, clothes and love.","vi":"Cha mẹ chu cấp cho con cái thức ăn, quần áo và tình yêu thương."}]', '[{"phrase":"provide information"},{"phrase":"provide a service"},{"phrase":"provide somebody with something"}]', 'provide sb with sth = provide sth for sb', '/prəˈvaɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/provi/provide__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 8, 'name', 'tên', 'noun', '[{"en":"What''s the name of that song you were singing?","vi":"Bài hát bạn vừa hát tên là gì vậy?"},{"en":"Please write your full name at the top of the page.","vi":"Vui lòng viết họ tên đầy đủ ở đầu trang."},{"en":"We haven''t chosen a name for the baby yet.","vi":"Chúng tôi vẫn chưa chọn được tên cho em bé."}]', '[{"phrase":"full name"},{"phrase":"first name"},{"phrase":"last name"},{"phrase":"choose a name"}]', NULL, '/neɪm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nam/name_/name__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 9, 'read', 'đọc', 'verb', '[{"en":"I usually read a book before I go to sleep.","vi":"Tôi thường đọc sách trước khi đi ngủ."},{"en":"Have you read the email from your manager?","vi":"Bạn đã đọc email của quản lý chưa?"},{"en":"My son learned to read when he was five.","vi":"Con trai tôi biết đọc khi lên năm tuổi."}]', '[{"phrase":"read a book"},{"phrase":"read the news"},{"phrase":"read aloud"},{"phrase":"read carefully"}]', 'read – read – read (quá khứ đọc là /red/)', '/riːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/read_/read__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 10, 'friend', 'bạn; bạn bè', 'noun', '[{"en":"I''m meeting a friend for coffee this afternoon.","vi":"Chiều nay tôi đi uống cà phê với một người bạn."},{"en":"She made a lot of new friends at university.","vi":"Cô ấy đã kết được nhiều bạn mới ở trường đại học."},{"en":"My best friend and I have known each other for years.","vi":"Tôi và bạn thân đã quen nhau nhiều năm rồi."}]', '[{"phrase":"best friend"},{"phrase":"make friends"},{"phrase":"close friend"},{"phrase":"old friend"}]', NULL, '/frend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fri/frien/friend__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 11, 'month', 'tháng', 'noun', '[{"en":"We''re going on vacation to the beach next month.","vi":"Tháng sau chúng tôi sẽ đi nghỉ ở biển."},{"en":"I pay my phone bill at the end of every month.","vi":"Tôi trả tiền điện thoại vào cuối mỗi tháng."},{"en":"She has been learning English for six months.","vi":"Cô ấy đã học tiếng Anh được sáu tháng."}]', '[{"phrase":"next month"},{"phrase":"last month"},{"phrase":"every month"},{"phrase":"the end of the month"}]', NULL, '/mʌnθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mon/month/month__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 12, 'large', 'lớn; rộng', 'adjective', '[{"en":"They live in a large house near the park.","vi":"Họ sống trong một ngôi nhà lớn gần công viên."},{"en":"Would you like a small or large coffee?","vi":"Bạn muốn cà phê cỡ nhỏ hay cỡ lớn?"},{"en":"A large number of students took the exam this year.","vi":"Năm nay có một số lượng lớn học sinh tham gia kỳ thi."}]', '[{"phrase":"a large number of"},{"phrase":"a large amount of"},{"phrase":"large family"}]', NULL, '/lɑːrdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lar/large/large__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 13, 'business', 'kinh doanh; doanh nghiệp', 'noun', '[{"en":"My parents run a small business selling flowers.","vi":"Bố mẹ tôi có một doanh nghiệp nhỏ chuyên bán hoa."},{"en":"He often travels to other countries on business.","vi":"Anh ấy thường đi công tác nước ngoài."},{"en":"She wants to study business at university.","vi":"Cô ấy muốn học ngành kinh doanh ở đại học."}]', '[{"phrase":"run a business"},{"phrase":"small business"},{"phrase":"on business"},{"phrase":"business trip"}]', NULL, '/ˈbɪznəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bus/busin/business__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 14, 'without', 'không có; mà không', 'preposition', '[{"en":"I never drink coffee without milk and sugar.","vi":"Tôi không bao giờ uống cà phê mà không cho sữa và đường."},{"en":"She left the room without saying a word.","vi":"Cô ấy rời khỏi phòng mà không nói một lời."},{"en":"We couldn''t have finished the project without your help.","vi":"Nếu không có sự giúp đỡ của bạn, chúng tôi đã không thể hoàn thành dự án."}]', '[{"phrase":"without saying a word"},{"phrase":"without a doubt"},{"phrase":"without warning"}]', NULL, '/wɪˈðaʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wit/witho/without__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 15, 'information', 'thông tin', 'noun', '[{"en":"You can find more information on our website.","vi":"Bạn có thể tìm thêm thông tin trên trang web của chúng tôi."},{"en":"Thanks for the useful information about the bus schedule.","vi":"Cảm ơn bạn vì thông tin hữu ích về lịch xe buýt."},{"en":"Please don''t share your personal information with strangers online.","vi":"Vui lòng không chia sẻ thông tin cá nhân với người lạ trên mạng."}]', '[{"phrase":"more information"},{"phrase":"personal information"},{"phrase":"useful information"},{"phrase":"information about"}]', 'không đếm được', '/ˌɪnfərˈmeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infor/information__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 16, 'open', 'mở; mở cửa', 'verb', '[{"en":"Could you open the window? It''s hot in here.","vi":"Bạn mở cửa sổ giúp tôi được không? Trong này nóng quá."},{"en":"The new library will open to the public next Monday.","vi":"Thư viện mới sẽ mở cửa đón mọi người vào thứ Hai tới."},{"en":"What time does the bank open on Saturdays?","vi":"Ngân hàng mở cửa lúc mấy giờ vào thứ Bảy?"}]', '[{"phrase":"open the window"},{"phrase":"open the door"},{"phrase":"open an account"}]', NULL, '/ˈəʊpən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ope/open_/open__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 17, 'order', 'thứ tự; đơn hàng; mệnh lệnh', 'noun', '[{"en":"Put the photos in order from oldest to newest.","vi":"Hãy sắp xếp ảnh theo thứ tự từ cũ nhất đến mới nhất."},{"en":"Your order will arrive in three to five days.","vi":"Đơn hàng của bạn sẽ được giao trong ba đến năm ngày."},{"en":"The manager gave orders to close the store early.","vi":"Quản lý đã ra lệnh đóng cửa hàng sớm."}]', '[{"phrase":"in order"},{"phrase":"place an order"},{"phrase":"give orders"}]', NULL, '/ˈɔːrdər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ord/order/order__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 18, 'government', 'chính phủ; chính quyền', 'noun', '[{"en":"The government is building a new hospital in our town.","vi":"Chính phủ đang xây một bệnh viện mới ở thị trấn của chúng tôi."},{"en":"She works for the local government as an engineer.","vi":"Cô ấy làm kỹ sư cho chính quyền địa phương."},{"en":"The government gives free school meals to young children.","vi":"Chính phủ cấp bữa ăn miễn phí ở trường cho trẻ nhỏ."}]', '[{"phrase":"local government"},{"phrase":"central government"},{"phrase":"work for the government"}]', NULL, '/ˈɡʌvərnmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gov/gover/government__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 19, 'word', 'từ; lời', 'noun', '[{"en":"I don''t know what this word means in English.","vi":"Tôi không biết từ này trong tiếng Anh nghĩa là gì."},{"en":"Can I have a word with you after class?","vi":"Sau giờ học tôi nói chuyện với bạn một chút được không?"},{"en":"He promised to help, and he kept his word.","vi":"Anh ấy hứa sẽ giúp và anh ấy đã giữ lời."}]', '[{"phrase":"in other words"},{"phrase":"have a word with"},{"phrase":"keep your word"}]', NULL, '/wɜːrd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wor/word_/word__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 20, 'issue', 'vấn đề; số báo', 'noun', '[{"en":"Money is a big issue for many students.","vi":"Tiền bạc là một vấn đề lớn với nhiều sinh viên."},{"en":"If you have any issues with the app, please contact us.","vi":"Nếu bạn gặp vấn đề gì với ứng dụng, vui lòng liên hệ với chúng tôi."},{"en":"Did you read the latest issue of the magazine?","vi":"Bạn đã đọc số mới nhất của tạp chí chưa?"}]', '[{"phrase":"a big issue"},{"phrase":"deal with an issue"},{"phrase":"the latest issue"}]', NULL, '/ˈɪʃuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/iss/issue/issue__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 21, 'market', 'chợ; thị trường', 'noun', '[{"en":"My grandmother buys fresh vegetables at the market every morning.","vi":"Bà tôi mua rau tươi ở chợ mỗi sáng."},{"en":"There''s a night market near our hotel.","vi":"Gần khách sạn của chúng tôi có một chợ đêm."},{"en":"The job market is very difficult for young people right now.","vi":"Hiện nay thị trường việc làm rất khó khăn với người trẻ."}]', '[{"phrase":"go to the market"},{"phrase":"night market"},{"phrase":"job market"}]', NULL, '/ˈmɑːrkɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mar/marke/market__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 22, 'pay', 'trả tiền; thanh toán', 'verb', '[{"en":"Can I pay by credit card, or only in cash?","vi":"Tôi có thể thanh toán bằng thẻ tín dụng không, hay chỉ bằng tiền mặt?"},{"en":"I paid twenty dollars for this shirt.","vi":"Tôi đã trả hai mươi đô la cho chiếc áo này."},{"en":"Let me pay for dinner tonight, since you paid last time.","vi":"Tối nay để tôi trả tiền bữa tối nhé, vì lần trước bạn trả rồi."}]', '[{"phrase":"pay for"},{"phrase":"pay by card"},{"phrase":"pay in cash"},{"phrase":"pay the bill"}]', 'pay – paid – paid', '/peɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pay/pay__/pay__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 23, 'build', 'xây; xây dựng', 'verb', '[{"en":"My father built this house thirty years ago.","vi":"Bố tôi đã xây ngôi nhà này ba mươi năm trước."},{"en":"They''re building a new bridge across the river.","vi":"Họ đang xây một cây cầu mới bắc qua sông."},{"en":"It takes time to build trust with new customers.","vi":"Cần có thời gian để xây dựng lòng tin với khách hàng mới."}]', '[{"phrase":"build a house"},{"phrase":"build a bridge"},{"phrase":"build trust"}]', 'build – built – built', '/bɪld/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bui/build/build__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 24, 'hold', 'cầm; nắm; tổ chức', 'verb', '[{"en":"Can you hold my bag for a minute?","vi":"Bạn cầm giúp tôi cái túi một lát được không?"},{"en":"The little girl held her mother''s hand tightly.","vi":"Cô bé nắm chặt tay mẹ."},{"en":"The school will hold a meeting for parents on Friday.","vi":"Nhà trường sẽ tổ chức một buổi họp phụ huynh vào thứ Sáu."}]', '[{"phrase":"hold a meeting"},{"phrase":"hold somebody''s hand"},{"phrase":"hold the door"}]', 'hold – held – held', '/həʊld/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hol/hold_/hold__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 25, 'service', 'dịch vụ; sự phục vụ', 'noun', '[{"en":"The food was good, but the service was very slow.","vi":"Đồ ăn ngon nhưng phục vụ rất chậm."},{"en":"There is no bus service on public holidays.","vi":"Không có dịch vụ xe buýt vào các ngày lễ."},{"en":"Please call customer service if you have any problems.","vi":"Vui lòng gọi bộ phận chăm sóc khách hàng nếu bạn gặp bất kỳ vấn đề nào."}]', '[{"phrase":"customer service"},{"phrase":"good service"},{"phrase":"bus service"},{"phrase":"provide a service"}]', NULL, '/ˈsɜːrvɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/servi/service__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 26, 'against', 'phản đối; đấu với; dựa vào', 'preposition', '[{"en":"We''re playing against a very strong team on Saturday.","vi":"Thứ Bảy này chúng tôi sẽ đấu với một đội rất mạnh."},{"en":"He leaned his bike against the wall.","vi":"Anh ấy dựa xe đạp vào tường."},{"en":"My parents were against the idea of me moving abroad.","vi":"Bố mẹ tôi phản đối việc tôi chuyển ra nước ngoài."}]', '[{"phrase":"against the law"},{"phrase":"against the wall"},{"phrase":"play against"}]', NULL, '/əˈɡenst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aga/again/against__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 27, 'believe', 'tin; tin rằng', 'verb', '[{"en":"I can''t believe we''ve been living here for ten years.","vi":"Tôi không thể tin là chúng tôi đã sống ở đây mười năm rồi."},{"en":"Do you believe everything you read online?","vi":"Bạn có tin mọi thứ bạn đọc trên mạng không?"},{"en":"She believes that anyone can learn a new language.","vi":"Cô ấy tin rằng ai cũng có thể học một ngôn ngữ mới."}]', '[{"phrase":"can''t believe"},{"phrase":"believe in"},{"phrase":"strongly believe"}]', NULL, '/bɪˈliːv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bel/belie/believe__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 28, 'second', 'thứ hai; giây', 'adjective', '[{"en":"I''m visiting this city for the second time.","vi":"Đây là lần thứ hai tôi đến thăm thành phố này."},{"en":"She came second in the school running race.","vi":"Cô ấy về nhì trong cuộc thi chạy của trường."},{"en":"It only takes thirty seconds to heat the milk.","vi":"Chỉ mất ba mươi giây để hâm nóng sữa."}]', '[{"phrase":"for the second time"},{"phrase":"a few seconds"},{"phrase":"wait a second"}]', NULL, '/ˈsekənd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secon/second__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 29, 'though', 'mặc dù; tuy vậy', 'conjunction', '[{"en":"Though it was raining, we still went for a walk.","vi":"Mặc dù trời mưa, chúng tôi vẫn đi dạo."},{"en":"She kept working even though she felt sick.","vi":"Cô ấy vẫn tiếp tục làm việc dù đang bị ốm."},{"en":"The room was small; it was very clean, though.","vi":"Căn phòng nhỏ, tuy vậy lại rất sạch sẽ."}]', '[{"phrase":"even though"},{"phrase":"as though"}]', NULL, '/ðəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tho/thoug/though__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-05', 30, 'love', 'yêu; rất thích', 'verb', '[{"en":"She loves her family more than anything.","vi":"Cô ấy yêu gia đình mình hơn bất cứ điều gì."},{"en":"My kids love playing in the snow.","vi":"Các con tôi rất thích chơi đùa trong tuyết."},{"en":"I''d love to come to your party on Saturday.","vi":"Tôi rất muốn đến dự bữa tiệc của bạn vào thứ Bảy."}]', '[{"phrase":"would love to"},{"phrase":"love doing something"},{"phrase":"fall in love"}]', NULL, '/lʌv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lov/love_/love__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-1-06', 'ngsl-1', 'Thông dụng 1–500 · Bộ 6', 'New General Service List, thứ hạng 1–500', '#3da9fc', 'BookOpen', 6);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 1, 'increase', 'tăng; làm tăng', 'verb', '[{"en":"The café increased its prices last month.","vi":"Quán cà phê đã tăng giá vào tháng trước."},{"en":"Her salary increased by ten percent this year.","vi":"Lương của cô ấy đã tăng mười phần trăm trong năm nay."},{"en":"The number of students in my class has increased to forty.","vi":"Số học sinh trong lớp tôi đã tăng lên bốn mươi."}]', '[{"phrase":"increase by"},{"phrase":"increase sharply"},{"phrase":"increase prices"},{"phrase":"increase the number of"}]', NULL, '/ɪnˈkriːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incre/increase__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 2, 'job', 'công việc; việc làm', 'noun', '[{"en":"My brother just got a new job at a hospital.","vi":"Anh trai tôi vừa có công việc mới ở một bệnh viện."},{"en":"She is looking for a part-time job near her school.","vi":"Cô ấy đang tìm một công việc bán thời gian gần trường."},{"en":"He lost his job when the factory closed.","vi":"Anh ấy mất việc khi nhà máy đóng cửa."}]', '[{"phrase":"get a job"},{"phrase":"lose your job"},{"phrase":"part-time job"},{"phrase":"look for a job"}]', NULL, '/dʒɑːb/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/job/job__/job__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 3, 'plan', 'kế hoạch; dự định', 'noun', '[{"en":"Do you have any plans for the weekend?","vi":"Bạn có kế hoạch gì cho cuối tuần không?"},{"en":"Our plan is to leave early and avoid the traffic.","vi":"Kế hoạch của chúng tôi là đi sớm để tránh kẹt xe."},{"en":"Everything at the wedding went according to plan.","vi":"Mọi việc trong đám cưới đều diễn ra đúng kế hoạch."}]', '[{"phrase":"make plans"},{"phrase":"have plans"},{"phrase":"according to plan"},{"phrase":"change of plan"}]', NULL, '/plæn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/plan_/plan__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 4, 'result', 'kết quả', 'noun', '[{"en":"We are still waiting for the results of the blood test.","vi":"Chúng tôi vẫn đang chờ kết quả xét nghiệm máu."},{"en":"As a result of the storm, all flights were canceled.","vi":"Do cơn bão, tất cả các chuyến bay đều bị hủy."},{"en":"She studied hard and got excellent results in her exams.","vi":"Cô ấy học chăm chỉ và đạt kết quả xuất sắc trong các kỳ thi."}]', '[{"phrase":"as a result"},{"phrase":"exam results"},{"phrase":"get results"},{"phrase":"final result"}]', NULL, '/rɪˈzʌlt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resul/result__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 5, 'away', 'xa; đi khỏi; vắng nhà', 'adverb', '[{"en":"The nearest supermarket is about two kilometers away from here.","vi":"Siêu thị gần nhất cách đây khoảng hai cây số."},{"en":"The dog ran away when it heard the loud noise.","vi":"Con chó bỏ chạy khi nghe thấy tiếng động lớn."},{"en":"My parents are away on vacation until next Friday.","vi":"Bố mẹ tôi đi nghỉ vắng nhà cho đến thứ Sáu tuần sau."}]', '[{"phrase":"far away"},{"phrase":"go away"},{"phrase":"run away"},{"phrase":"put away"}]', NULL, '/əˈweɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/awa/away_/away__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 6, 'example', 'ví dụ; tấm gương', 'noun', '[{"en":"Can you give me an example of how to use this word?","vi":"Bạn có thể cho tôi một ví dụ về cách dùng từ này không?"},{"en":"Many fruits, for example apples and oranges, are rich in vitamin C.","vi":"Nhiều loại trái cây, ví dụ như táo và cam, rất giàu vitamin C."},{"en":"Parents should set a good example for their children.","vi":"Cha mẹ nên làm gương tốt cho con cái."}]', '[{"phrase":"for example"},{"phrase":"give an example"},{"phrase":"set an example"},{"phrase":"good example"}]', NULL, '/ɪɡˈzæmpl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exa/examp/example__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 7, 'happen', 'xảy ra; tình cờ', 'verb', '[{"en":"Tell me exactly what happened at the party.","vi":"Kể cho tôi nghe chính xác chuyện gì đã xảy ra ở bữa tiệc."},{"en":"Accidents often happen when drivers are tired.","vi":"Tai nạn thường xảy ra khi tài xế mệt mỏi."},{"en":"I happened to meet my old teacher at the market.","vi":"Tôi tình cờ gặp lại thầy giáo cũ ở chợ."}]', '[{"phrase":"what happened"},{"phrase":"happen again"},{"phrase":"happen to"}]', NULL, '/ˈhæpən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hap/happe/happen__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 8, 'offer', 'đề nghị; mời; cung cấp', 'verb', '[{"en":"My neighbor offered to help me move the sofa.","vi":"Người hàng xóm đề nghị giúp tôi chuyển chiếc ghế sofa."},{"en":"She offered me a cup of tea when I arrived.","vi":"Cô ấy mời tôi một tách trà khi tôi đến."},{"en":"The hotel offers free breakfast to all its guests.","vi":"Khách sạn cung cấp bữa sáng miễn phí cho tất cả khách lưu trú."}]', '[{"phrase":"offer to help"},{"phrase":"offer advice"},{"phrase":"offer a job"}]', 'offer to do something: đề nghị làm gì', '/ˈɔːfər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/off/offer/offer__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 9, 'young', 'trẻ; nhỏ tuổi', 'adjective', '[{"en":"My grandmother was a teacher when she was young.","vi":"Bà tôi từng là giáo viên khi bà còn trẻ."},{"en":"The park is full of young families on Sundays.","vi":"Vào Chủ nhật, công viên có rất nhiều gia đình trẻ."},{"en":"He is still too young to drive a car.","vi":"Cậu bé vẫn còn quá nhỏ để lái ô tô."}]', '[{"phrase":"young people"},{"phrase":"young children"},{"phrase":"young family"},{"phrase":"too young"}]', NULL, '/jʌŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/you/young/young__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 10, 'close', 'đóng; đóng cửa; nhắm (mắt)', 'verb', '[{"en":"Could you close the window because it''s getting cold?","vi":"Bạn đóng cửa sổ lại được không, vì trời đang trở lạnh?"},{"en":"The bank closes at four o''clock on Fridays.","vi":"Ngân hàng đóng cửa lúc bốn giờ vào các ngày thứ Sáu."},{"en":"Close your eyes and try to relax for a minute.","vi":"Hãy nhắm mắt lại và cố gắng thư giãn một chút."}]', '[{"phrase":"close the door"},{"phrase":"close the window"},{"phrase":"close your eyes"}]', 'Tính từ close (đọc /kləʊs/) nghĩa là "gần"', '/kləʊz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clo/close/close__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 11, 'program', 'chương trình', 'noun', '[{"en":"My favorite TV program starts at eight tonight.","vi":"Chương trình truyền hình yêu thích của tôi bắt đầu lúc tám giờ tối nay."},{"en":"She joined an exchange program in Japan last year.","vi":"Năm ngoái cô ấy tham gia một chương trình trao đổi ở Nhật Bản."},{"en":"You need to install this program on your computer first.","vi":"Trước tiên bạn cần cài đặt chương trình này trên máy tính."}]', '[{"phrase":"TV program"},{"phrase":"exchange program"},{"phrase":"training program"},{"phrase":"computer program"}]', 'Anh: programme · Mỹ: program', '/ˈprəʊɡræm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/progr/program__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 12, 'lead', 'dẫn; dẫn đến; lãnh đạo', 'verb', '[{"en":"This path leads directly to the beach.","vi":"Con đường này dẫn thẳng ra bãi biển."},{"en":"Eating too much sugar can lead to health problems.","vi":"Ăn quá nhiều đường có thể dẫn đến các vấn đề sức khỏe."},{"en":"She led a team of ten engineers on the project.","vi":"Cô ấy lãnh đạo một nhóm gồm mười kỹ sư trong dự án đó."}]', '[{"phrase":"lead to"},{"phrase":"lead a team"},{"phrase":"lead the way"}]', 'lead – led – led', '/liːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/lead_/lead__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 13, 'buy', 'mua', 'verb', '[{"en":"I bought a new pair of shoes for the party.","vi":"Tôi đã mua một đôi giày mới để đi dự tiệc."},{"en":"Where can I buy tickets for the concert?","vi":"Tôi có thể mua vé buổi hòa nhạc ở đâu?"},{"en":"They are saving money to buy a house next year.","vi":"Họ đang tiết kiệm tiền để mua nhà vào năm sau."}]', '[{"phrase":"buy tickets"},{"phrase":"buy a house"},{"phrase":"buy a present"}]', 'buy – bought – bought', '/baɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/buy/buy__/buy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 14, 'understand', 'hiểu', 'verb', '[{"en":"Sorry, I don''t understand what you mean.","vi":"Xin lỗi, tôi không hiểu ý bạn."},{"en":"My parents always understand how I feel.","vi":"Bố mẹ tôi luôn hiểu cảm giác của tôi."},{"en":"She understood the lesson after the teacher gave another example.","vi":"Cô ấy đã hiểu bài sau khi giáo viên đưa thêm một ví dụ nữa."}]', '[{"phrase":"fully understand"},{"phrase":"easy to understand"},{"phrase":"understand what you mean"}]', 'understand – understood – understood', '/ˌʌndərˈstænd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/understand__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 15, 'thank', 'cảm ơn', 'verb', '[{"en":"I want to thank you for all your help.","vi":"Tôi muốn cảm ơn bạn vì mọi sự giúp đỡ."},{"en":"She thanked the driver and got off the bus.","vi":"Cô ấy cảm ơn tài xế rồi xuống xe buýt."},{"en":"Don''t forget to thank your grandmother for the gift.","vi":"Đừng quên cảm ơn bà về món quà nhé."}]', '[{"phrase":"thank you"},{"phrase":"thank you for"},{"phrase":"thank you very much"}]', 'thank somebody for something', '/θæŋk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tha/thank/thank__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 16, 'far', 'xa', 'adverb', '[{"en":"How far is the airport from the city center?","vi":"Sân bay cách trung tâm thành phố bao xa?"},{"en":"We didn''t walk very far because it started to rain.","vi":"Chúng tôi không đi bộ xa lắm vì trời bắt đầu mưa."},{"en":"My school isn''t far from my house.","vi":"Trường của tôi cách nhà không xa."}]', '[{"phrase":"how far"},{"phrase":"far away"},{"phrase":"far from"},{"phrase":"so far"}]', 'far – farther/further – farthest/furthest', '/fɑːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/far/far__/far__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 17, 'today', 'hôm nay; ngày nay', 'adverb', '[{"en":"I''ll call you back later today, after my meeting.","vi":"Hôm nay tôi sẽ gọi lại cho bạn sau khi họp xong."},{"en":"What are you doing today after work?","vi":"Hôm nay tan làm bạn định làm gì?"},{"en":"Young people today spend a lot of time on their phones.","vi":"Giới trẻ ngày nay dành nhiều thời gian cho điện thoại."}]', '[{"phrase":"later today"},{"phrase":"earlier today"},{"phrase":"from today"}]', NULL, '/təˈdeɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tod/today/today__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 18, 'hour', 'giờ; tiếng đồng hồ', 'noun', '[{"en":"The flight to Hanoi takes about two hours.","vi":"Chuyến bay đến Hà Nội mất khoảng hai tiếng."},{"en":"I usually work eight hours a day.","vi":"Tôi thường làm việc tám tiếng mỗi ngày."},{"en":"The store''s opening hours are from nine to five.","vi":"Giờ mở cửa của cửa hàng là từ chín giờ đến năm giờ."}]', '[{"phrase":"half an hour"},{"phrase":"opening hours"},{"phrase":"working hours"},{"phrase":"an hour ago"}]', 'h câm, nên nói "an hour"', '/ˈaʊər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hou/hour_/hour__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 19, 'student', 'học sinh; sinh viên', 'noun', '[{"en":"There are thirty students in my English class.","vi":"Lớp tiếng Anh của tôi có ba mươi học sinh."},{"en":"My sister is a medical student in her third year.","vi":"Chị tôi là sinh viên y năm thứ ba."},{"en":"Students get a discount at this museum on weekdays.","vi":"Học sinh, sinh viên được giảm giá ở bảo tàng này vào các ngày trong tuần."}]', '[{"phrase":"medical student"},{"phrase":"university student"},{"phrase":"student discount"},{"phrase":"exchange student"}]', NULL, '/ˈstuːdnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/stu/stude/student__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 20, 'face', 'mặt; khuôn mặt', 'noun', '[{"en":"Go and wash your face before breakfast.","vi":"Con đi rửa mặt trước khi ăn sáng đi."},{"en":"She had a big smile on her face all day.","vi":"Cả ngày trên mặt cô ấy luôn nở một nụ cười thật tươi."},{"en":"I''ll never forget the look on his face.","vi":"Tôi sẽ không bao giờ quên vẻ mặt của anh ấy lúc đó."}]', '[{"phrase":"wash your face"},{"phrase":"face to face"},{"phrase":"smile on your face"}]', 'Động từ face: đối mặt (face a problem)', '/feɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fac/face_/face__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 21, 'hope', 'hy vọng; mong', 'verb', '[{"en":"I really hope you feel better soon.","vi":"Tôi thật lòng mong bạn sớm khỏe lại."},{"en":"We''re hoping to visit our grandparents this summer.","vi":"Chúng tôi hy vọng được về thăm ông bà vào mùa hè này."},{"en":"She hopes to become a doctor one day.","vi":"Cô ấy hy vọng một ngày nào đó sẽ trở thành bác sĩ."}]', '[{"phrase":"I hope so"},{"phrase":"hope for the best"},{"phrase":"really hope"}]', 'hope to do something; hope (that) ...', '/həʊp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hop/hope_/hope__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 22, 'idea', 'ý tưởng; ý kiến', 'noun', '[{"en":"That''s a great idea for a birthday present.","vi":"Đó là một ý tưởng tuyệt vời cho món quà sinh nhật."},{"en":"It was her idea to go camping this weekend.","vi":"Đi cắm trại cuối tuần này là ý của cô ấy."},{"en":"Do you think it''s a good idea to buy a car now?","vi":"Bạn có nghĩ bây giờ mua ô tô là ý hay không?"}]', '[{"phrase":"good idea"},{"phrase":"great idea"},{"phrase":"have no idea"},{"phrase":"come up with an idea"}]', NULL, '/aɪˈdiːə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ide/idea_/idea__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 23, 'cost', 'có giá; tốn', 'verb', '[{"en":"How much did your new laptop cost?","vi":"Chiếc laptop mới của bạn giá bao nhiêu?"},{"en":"The trip cost us more than we expected.","vi":"Chuyến đi khiến chúng tôi tốn nhiều tiền hơn dự kiến."},{"en":"Fixing the roof will cost about five hundred dollars.","vi":"Sửa mái nhà sẽ tốn khoảng năm trăm đô la."}]', '[{"phrase":"cost a lot"},{"phrase":"cost money"},{"phrase":"cost a fortune"}]', 'cost – cost – cost', '/kɔːst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cos/cost_/cost__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 24, 'less', 'ít hơn', 'determiner', '[{"en":"You should eat less sugar and more vegetables.","vi":"Bạn nên ăn ít đường hơn và ăn nhiều rau hơn."},{"en":"I spend less time on my phone than I used to.","vi":"Bây giờ tôi dành ít thời gian cho điện thoại hơn trước."},{"en":"It took less than ten minutes to get there.","vi":"Mất chưa đầy mười phút để đến đó."}]', '[{"phrase":"less than"},{"phrase":"less time"},{"phrase":"less money"},{"phrase":"more or less"}]', 'Dùng với danh từ không đếm được; danh từ đếm được dùng fewer', '/les/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/les/less_/less__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 25, 'room', 'phòng; chỗ trống', 'noun', '[{"en":"My room is on the second floor.","vi":"Phòng của tôi ở tầng hai."},{"en":"We booked a double room at a small hotel by the beach.","vi":"Chúng tôi đã đặt một phòng đôi ở một khách sạn nhỏ gần biển."},{"en":"Is there enough room in the car for one more person?","vi":"Trong xe còn đủ chỗ cho thêm một người nữa không?"}]', '[{"phrase":"living room"},{"phrase":"double room"},{"phrase":"book a room"},{"phrase":"make room for"}]', 'Nghĩa "chỗ trống" không đếm được', '/ruːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/roo/room_/room__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 26, 'until', 'đến; cho đến khi', 'preposition', '[{"en":"The library is open until nine o''clock tonight.","vi":"Thư viện mở cửa đến chín giờ tối nay."},{"en":"I lived with my parents until I was twenty-five.","vi":"Tôi sống cùng bố mẹ cho đến năm hai mươi lăm tuổi."},{"en":"Please wait here until the doctor calls your name.","vi":"Vui lòng chờ ở đây cho đến khi bác sĩ gọi tên bạn."}]', '[{"phrase":"until now"},{"phrase":"until then"},{"phrase":"wait until"}]', 'not ... until: mãi đến ... mới', '/ənˈtɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unt/until/until__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 27, 'reason', 'lý do', 'noun', '[{"en":"What was the reason for the delay?","vi":"Lý do của việc chậm trễ là gì?"},{"en":"She left the job for personal reasons.","vi":"Cô ấy nghỉ việc vì lý do cá nhân."},{"en":"There is no reason to worry about the exam.","vi":"Không có lý do gì phải lo lắng về kỳ thi."}]', '[{"phrase":"reason for"},{"phrase":"for some reason"},{"phrase":"personal reasons"},{"phrase":"good reason"}]', 'reason for something', '/ˈriːzn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reaso/reason__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 28, 'form', 'mẫu đơn; hình thức; dạng', 'noun', '[{"en":"Please fill out this form and give it to the receptionist.","vi":"Vui lòng điền vào mẫu đơn này và nộp cho lễ tân."},{"en":"Cycling is a cheap and healthy form of transportation.","vi":"Đi xe đạp là một hình thức đi lại rẻ và tốt cho sức khỏe."},{"en":"Write the correct form of the verb in each blank.","vi":"Hãy viết dạng đúng của động từ vào mỗi chỗ trống."}]', '[{"phrase":"fill out a form"},{"phrase":"application form"},{"phrase":"a form of"}]', NULL, '/fɔːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/form_/form__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 29, 'spend', 'tiêu; dành; trải qua', 'verb', '[{"en":"She spends too much money on clothes.","vi":"Cô ấy tiêu quá nhiều tiền vào quần áo."},{"en":"We spent the whole weekend at my uncle''s farm.","vi":"Chúng tôi đã ở trang trại của chú tôi suốt cả cuối tuần."},{"en":"How much time do you spend on homework every day?","vi":"Mỗi ngày bạn dành bao nhiêu thời gian làm bài tập về nhà?"}]', '[{"phrase":"spend money"},{"phrase":"spend time"},{"phrase":"spend the weekend"}]', 'spend – spent – spent; spend time/money on something', '/spend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/spend/spend__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-06', 30, 'head', 'đầu; người đứng đầu', 'noun', '[{"en":"He hit his head on the door.","vi":"Anh ấy bị đập đầu vào cửa."},{"en":"My head hurts because I didn''t sleep well.","vi":"Tôi đau đầu vì ngủ không ngon."},{"en":"My aunt is the head of a small primary school.","vi":"Dì tôi là hiệu trưởng một trường tiểu học nhỏ."}]', '[{"phrase":"shake your head"},{"phrase":"hit your head"},{"phrase":"head of"}]', NULL, '/hed/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/head_/head__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-1-07', 'ngsl-1', 'Thông dụng 1–500 · Bộ 7', 'New General Service List, thứ hạng 1–500', '#3da9fc', 'BookOpen', 7);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 1, 'car', 'xe hơi; ô tô', 'noun', '[{"en":"My brother drives his car to work every day.","vi":"Anh trai tôi lái xe hơi đi làm mỗi ngày."},{"en":"We rented a car for our trip to the mountains.","vi":"Chúng tôi thuê một chiếc ô tô cho chuyến đi lên núi."},{"en":"Could you help me carry these bags to the car?","vi":"Bạn có thể giúp tôi mang mấy cái túi này ra xe không?"}]', '[{"phrase":"drive a car"},{"phrase":"rent a car"},{"phrase":"car accident"},{"phrase":"by car"}]', NULL, '/kɑːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/car__/car__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 2, 'learn', 'học; biết được', 'verb', '[{"en":"My daughter is learning to swim this summer.","vi":"Mùa hè này con gái tôi đang học bơi."},{"en":"I want to learn English so I can travel more easily.","vi":"Tôi muốn học tiếng Anh để có thể đi du lịch dễ dàng hơn."},{"en":"We only learned about the change the next morning.","vi":"Mãi đến sáng hôm sau chúng tôi mới biết về sự thay đổi đó."}]', '[{"phrase":"learn English"},{"phrase":"learn to swim"},{"phrase":"learn from your mistakes"},{"phrase":"learn about"}]', 'Mỹ: learned · Anh: learned/learnt', '/lɜːrn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/learn/learn__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 3, 'level', 'mức; trình độ', 'noun', '[{"en":"Stress levels are often high before exams.","vi":"Mức độ căng thẳng thường cao trước kỳ thi."},{"en":"What level of English do you need for this job?","vi":"Công việc này cần trình độ tiếng Anh ở mức nào?"},{"en":"The water level in the river rose after the heavy rain.","vi":"Mực nước sông dâng cao sau trận mưa lớn."}]', '[{"phrase":"high level"},{"phrase":"water level"},{"phrase":"advanced level"}]', NULL, '/ˈlevl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lev/level/level__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 4, 'person', 'người; cá nhân', 'noun', '[{"en":"She is the kindest person I have ever met.","vi":"Cô ấy là người tốt bụng nhất mà tôi từng gặp."},{"en":"Tickets for the show cost ten dollars per person.","vi":"Vé xem buổi biểu diễn có giá mười đô la mỗi người."},{"en":"Every person in the class has to give a short talk.","vi":"Mỗi người trong lớp đều phải thuyết trình ngắn."}]', '[{"phrase":"per person"},{"phrase":"in person"},{"phrase":"a nice person"}]', 'số nhiều thường dùng: people', '/ˈpɜːrsn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perso/person__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 5, 'experience', 'kinh nghiệm; trải nghiệm', 'noun', '[{"en":"Do you have any experience working with children?","vi":"Bạn có kinh nghiệm làm việc với trẻ em không?"},{"en":"Living abroad was a great experience for me.","vi":"Sống ở nước ngoài là một trải nghiệm tuyệt vời đối với tôi."},{"en":"She has ten years of experience as a nurse.","vi":"Cô ấy có mười năm kinh nghiệm làm y tá."}]', '[{"phrase":"work experience"},{"phrase":"years of experience"},{"phrase":"a great experience"}]', 'nghĩa "kinh nghiệm": không đếm được', '/ɪkˈspɪriəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/exper/experience__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 6, 'once', 'một lần; đã từng', 'adverb', '[{"en":"I go to the gym once a week.","vi":"Tôi đến phòng tập một lần mỗi tuần."},{"en":"We once lived in a small town near the sea.","vi":"Chúng tôi đã từng sống ở một thị trấn nhỏ gần biển."},{"en":"I have only been to Japan once.","vi":"Tôi mới chỉ đến Nhật Bản một lần."}]', '[{"phrase":"once a week"},{"phrase":"once again"},{"phrase":"at once"}]', NULL, '/wʌns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/onc/once_/once__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 7, 'member', 'thành viên; hội viên', 'noun', '[{"en":"She is the youngest member of the team.","vi":"Cô ấy là thành viên trẻ nhất của đội."},{"en":"All family members came home for the holiday.","vi":"Tất cả thành viên trong gia đình đều về nhà dịp lễ."},{"en":"Members of the gym can use the pool for free.","vi":"Hội viên của phòng tập được dùng hồ bơi miễn phí."}]', '[{"phrase":"family member"},{"phrase":"team member"},{"phrase":"become a member"}]', NULL, '/ˈmembər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mem/membe/member__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 8, 'enough', 'đủ', 'determiner', '[{"en":"We don''t have enough money to buy a new house.","vi":"Chúng tôi không có đủ tiền để mua nhà mới."},{"en":"Is there enough food for everyone at the party?","vi":"Có đủ đồ ăn cho mọi người ở bữa tiệc không?"},{"en":"He isn''t old enough to drive yet.","vi":"Cậu ấy chưa đủ tuổi để lái xe."}]', '[{"phrase":"enough money"},{"phrase":"enough time"},{"phrase":"old enough"}]', 'đứng trước danh từ (enough time), sau tính từ (old enough)', '/ɪˈnʌf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eno/enoug/enough__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 9, 'bad', 'xấu; tệ; có hại', 'adjective', '[{"en":"I had a really bad day at work today.","vi":"Hôm nay tôi đã có một ngày thật tệ ở chỗ làm."},{"en":"Eating too much sugar is bad for your teeth.","vi":"Ăn quá nhiều đường có hại cho răng."},{"en":"The weather was so bad that we stayed inside all day.","vi":"Thời tiết xấu đến mức chúng tôi ở trong nhà cả ngày."}]', '[{"phrase":"bad weather"},{"phrase":"bad news"},{"phrase":"bad for your health"},{"phrase":"bad day"}]', 'bad – worse – worst', '/bæd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bad/bad__/bad__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 10, 'city', 'thành phố', 'noun', '[{"en":"I grew up in a small village, but now I live in the city.","vi":"Tôi lớn lên ở một ngôi làng nhỏ, nhưng giờ tôi sống ở thành phố."},{"en":"The city center is always busy on weekends.","vi":"Trung tâm thành phố lúc nào cũng đông đúc vào cuối tuần."},{"en":"Which city would you most like to visit?","vi":"Bạn muốn đến thăm thành phố nào nhất?"}]', '[{"phrase":"city center"},{"phrase":"big city"},{"phrase":"capital city"},{"phrase":"city life"}]', NULL, '/ˈsɪti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cit/city_/city__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 11, 'night', 'đêm; buổi tối', 'noun', '[{"en":"I couldn''t sleep last night because of the noise.","vi":"Đêm qua tôi không ngủ được vì tiếng ồn."},{"en":"She works at a hospital and often works at night.","vi":"Cô ấy làm ở bệnh viện và thường làm việc vào ban đêm."},{"en":"Let''s have a movie night at home on Friday.","vi":"Tối thứ Sáu mình cùng xem phim ở nhà nhé."}]', '[{"phrase":"last night"},{"phrase":"at night"},{"phrase":"all night"},{"phrase":"good night"}]', NULL, '/naɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nig/night/night__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 12, 'able', 'có thể; có khả năng', 'adjective', '[{"en":"Will you be able to come to the meeting tomorrow?","vi":"Ngày mai bạn có thể đến dự cuộc họp không?"},{"en":"She was able to finish the report on time.","vi":"Cô ấy đã hoàn thành được bản báo cáo đúng hạn."},{"en":"After the operation, he wasn''t able to walk for a month.","vi":"Sau ca phẫu thuật, anh ấy không đi lại được trong một tháng."}]', '[{"phrase":"be able to"},{"phrase":"no longer able to"}]', 'be able to + động từ nguyên mẫu', '/ˈeɪbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abl/able_/able__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 13, 'support', 'ủng hộ; hỗ trợ; nuôi (gia đình)', 'verb', '[{"en":"My parents have always supported my decision to study abroad.","vi":"Bố mẹ tôi luôn ủng hộ quyết định đi du học của tôi."},{"en":"Our team supports customers by phone and email.","vi":"Nhóm của chúng tôi hỗ trợ khách hàng qua điện thoại và email."},{"en":"He works two jobs to support his family.","vi":"Anh ấy làm hai công việc để nuôi gia đình."}]', '[{"phrase":"support a decision"},{"phrase":"support your family"},{"phrase":"strongly support"},{"phrase":"fully support"}]', NULL, '/səˈpɔːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sup/suppo/support__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 14, 'whether', 'liệu; có... hay không', 'conjunction', '[{"en":"I''m not sure whether she will come tonight.","vi":"Tôi không chắc liệu tối nay cô ấy có đến không."},{"en":"Can you check whether the store is open on Sunday?","vi":"Bạn kiểm tra giúp xem cửa hàng có mở cửa vào Chủ nhật không nhé?"},{"en":"We''ll go to the beach whether it rains or not.","vi":"Dù trời có mưa hay không, chúng tôi vẫn sẽ đi biển."}]', '[{"phrase":"not sure whether"},{"phrase":"whether or not"},{"phrase":"decide whether"}]', NULL, '/ˈweðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whe/wheth/whether__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 15, 'line', 'hàng; dòng; đường kẻ', 'noun', '[{"en":"There was a long line outside the bakery this morning.","vi":"Sáng nay có một hàng dài người xếp trước tiệm bánh."},{"en":"Please read the first line of the poem aloud.","vi":"Hãy đọc to dòng đầu tiên của bài thơ."},{"en":"Draw a straight line across the page.","vi":"Hãy kẻ một đường thẳng ngang trang giấy."}]', '[{"phrase":"long line"},{"phrase":"wait in line"},{"phrase":"straight line"},{"phrase":"first line"}]', 'hàng người xếp: Mỹ: line · Anh: queue', '/laɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lin/line_/line__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 16, 'present', 'món quà; hiện tại', 'noun', '[{"en":"I need to buy a birthday present for my sister.","vi":"Tôi cần mua quà sinh nhật cho em gái."},{"en":"Thank you so much for the lovely present!","vi":"Cảm ơn bạn rất nhiều vì món quà dễ thương!"},{"en":"Try to forget the past and enjoy the present.","vi":"Hãy cố quên đi quá khứ và tận hưởng hiện tại."}]', '[{"phrase":"birthday present"},{"phrase":"wedding present"},{"phrase":"at present"}]', 'danh từ nhấn âm đầu; động từ present (trình bày) nhấn âm sau', '/ˈpreznt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prese/present__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 17, 'side', 'bên; phía; mặt', 'noun', '[{"en":"The bank is on the other side of the street.","vi":"Ngân hàng nằm ở phía bên kia đường."},{"en":"Which side are you on in this argument?","vi":"Trong cuộc tranh cãi này, bạn đứng về phía ai?"},{"en":"Write your answers on both sides of the paper.","vi":"Hãy viết câu trả lời lên cả hai mặt giấy."}]', '[{"phrase":"the other side"},{"phrase":"both sides"},{"phrase":"left side"},{"phrase":"take sides"}]', NULL, '/saɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sid/side_/side__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 18, 'quite', 'khá; hoàn toàn', 'adverb', '[{"en":"The test was quite difficult, but I think I passed.","vi":"Bài kiểm tra khá khó, nhưng tôi nghĩ mình đã đậu."},{"en":"It''s quite cold today, so bring a jacket.","vi":"Hôm nay trời khá lạnh, nên hãy mang theo áo khoác."},{"en":"You''re quite right; I made a mistake.","vi":"Bạn hoàn toàn đúng; tôi đã nhầm."}]', '[{"phrase":"quite good"},{"phrase":"quite a lot"},{"phrase":"quite right"},{"phrase":"not quite"}]', NULL, '/kwaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qui/quite/quite__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 19, 'although', 'mặc dù', 'conjunction', '[{"en":"Although it was raining, we went for a walk.","vi":"Mặc dù trời đang mưa, chúng tôi vẫn đi dạo."},{"en":"She went to work although she felt sick.","vi":"Cô ấy vẫn đi làm mặc dù cảm thấy không khỏe."},{"en":"I enjoyed the movie, although it was a bit long.","vi":"Tôi thích bộ phim, mặc dù nó hơi dài."}]', '[{"phrase":"although it was"},{"phrase":"although not always"}]', 'không dùng although và but trong cùng một câu', '/ɔːlˈðəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alt/altho/although__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 20, 'sure', 'chắc chắn; chắc', 'adjective', '[{"en":"Are you sure you locked the door?","vi":"Bạn có chắc là đã khóa cửa không?"},{"en":"I''m not sure what time the train leaves.","vi":"Tôi không chắc mấy giờ tàu chạy."},{"en":"Make sure you drink plenty of water during the hike.","vi":"Hãy nhớ uống nhiều nước trong suốt chuyến đi bộ đường dài."}]', '[{"phrase":"make sure"},{"phrase":"not sure"},{"phrase":"for sure"},{"phrase":"sure about"}]', NULL, '/ʃʊr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/sure_/sure__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 21, 'term', 'thuật ngữ; học kỳ; thời hạn', 'noun', '[{"en":"Can you explain what this medical term means?","vi":"Bạn có thể giải thích thuật ngữ y khoa này nghĩa là gì không?"},{"en":"The new school term starts in September.","vi":"Học kỳ mới bắt đầu vào tháng Chín."},{"en":"In the long term, learning a language will help your career.","vi":"Về lâu dài, học một ngoại ngữ sẽ giúp ích cho sự nghiệp của bạn."}]', '[{"phrase":"technical term"},{"phrase":"in the long term"},{"phrase":"school term"},{"phrase":"in terms of"}]', 'in terms of: xét về mặt', '/tɜːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ter/term_/term__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 22, 'least', 'ít nhất; tối thiểu', 'adverb', '[{"en":"You should sleep at least seven hours a night.","vi":"Bạn nên ngủ ít nhất bảy tiếng mỗi đêm."},{"en":"The trip was expensive, but at least the food was good.","vi":"Chuyến đi tốn kém, nhưng ít ra đồ ăn cũng ngon."},{"en":"Math is the subject I like the least at school.","vi":"Toán là môn tôi ít thích nhất ở trường."}]', '[{"phrase":"at least"},{"phrase":"the least"},{"phrase":"least expensive"}]', 'little – less – least', '/liːst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/least/least__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 23, 'age', 'tuổi; thời đại', 'noun', '[{"en":"She started playing the piano at the age of five.","vi":"Cô ấy bắt đầu chơi piano từ khi mới năm tuổi."},{"en":"People of all ages enjoy this game.","vi":"Người ở mọi lứa tuổi đều thích trò chơi này."},{"en":"We live in the digital age, so most people shop online.","vi":"Chúng ta sống trong thời đại kỹ thuật số, nên hầu hết mọi người đều mua sắm trực tuyến."}]', '[{"phrase":"at the age of"},{"phrase":"all ages"},{"phrase":"the same age"},{"phrase":"old age"}]', NULL, '/eɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/age/age__/age__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 24, 'low', 'thấp; nhỏ', 'adjective', '[{"en":"This chair is too low for the desk.","vi":"Cái ghế này quá thấp so với cái bàn."},{"en":"Prices at this market are very low.","vi":"Giá cả ở chợ này rất thấp."},{"en":"Please speak in a low voice; the baby is sleeping.","vi":"Làm ơn nói nhỏ thôi; em bé đang ngủ."}]', '[{"phrase":"low price"},{"phrase":"low voice"},{"phrase":"low temperature"},{"phrase":"low income"}]', NULL, '/ləʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/low/low__/low__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 25, 'speak', 'nói; nói chuyện', 'verb', '[{"en":"How many languages can your teacher speak?","vi":"Giáo viên của bạn nói được bao nhiêu thứ tiếng?"},{"en":"Could I speak to the manager, please?","vi":"Cho tôi nói chuyện với quản lý được không?"},{"en":"She spoke quietly so she wouldn''t wake the children.","vi":"Cô ấy nói khẽ để không làm bọn trẻ thức giấc."}]', '[{"phrase":"speak English"},{"phrase":"speak to"},{"phrase":"speak quietly"},{"phrase":"speak clearly"}]', 'speak – spoke – spoken', '/spiːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speak/speak__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 26, 'within', 'trong vòng; bên trong', 'preposition', '[{"en":"Please reply to this email within three days.","vi":"Vui lòng trả lời email này trong vòng ba ngày."},{"en":"The hotel is within walking distance of the beach.","vi":"Từ khách sạn có thể đi bộ ra bãi biển."},{"en":"Problems within the team need to be solved quickly.","vi":"Các vấn đề trong nội bộ nhóm cần được giải quyết nhanh chóng."}]', '[{"phrase":"within walking distance"},{"phrase":"within a week"},{"phrase":"within reach"}]', NULL, '/wɪˈðɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wit/withi/within__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 27, 'process', 'quá trình; quy trình', 'noun', '[{"en":"Learning a new language is a slow process.","vi":"Học một ngôn ngữ mới là một quá trình chậm rãi."},{"en":"The application process takes about two weeks.","vi":"Quy trình nộp đơn mất khoảng hai tuần."},{"en":"We are in the process of moving to a new apartment.","vi":"Chúng tôi đang trong quá trình chuyển đến căn hộ mới."}]', '[{"phrase":"in the process of"},{"phrase":"application process"},{"phrase":"a slow process"},{"phrase":"learning process"}]', NULL, '/ˈprɑːses/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proce/process__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 28, 'public', 'công cộng; công khai', 'adjective', '[{"en":"Smoking is not allowed in public places.","vi":"Không được hút thuốc ở nơi công cộng."},{"en":"I usually take public transportation to work.","vi":"Tôi thường đi làm bằng phương tiện công cộng."},{"en":"The results will be made public next week.","vi":"Kết quả sẽ được công bố công khai vào tuần tới."}]', '[{"phrase":"public transportation"},{"phrase":"public place"},{"phrase":"make public"},{"phrase":"in public"}]', NULL, '/ˈpʌblɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pub/publi/public__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 29, 'often', 'thường; hay', 'adverb', '[{"en":"How often do you visit your grandparents?","vi":"Bạn có hay về thăm ông bà không?"},{"en":"I often forget where I put my keys.","vi":"Tôi hay quên mình để chìa khóa ở đâu."},{"en":"It doesn''t often snow here in winter.","vi":"Ở đây mùa đông ít khi có tuyết."}]', '[{"phrase":"how often"},{"phrase":"quite often"},{"phrase":"very often"}]', NULL, '/ˈɔːfn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/oft/often/often__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-07', 30, 'train', 'tàu hỏa; chuyến tàu', 'noun', '[{"en":"We took the train from the city to the coast.","vi":"Chúng tôi đi tàu hỏa từ thành phố ra vùng biển."},{"en":"Hurry up, or we''ll miss the train!","vi":"Nhanh lên, không thì chúng ta sẽ lỡ chuyến tàu mất!"},{"en":"The next train to the airport leaves in ten minutes.","vi":"Chuyến tàu tiếp theo đi sân bay sẽ khởi hành sau mười phút nữa."}]', '[{"phrase":"take the train"},{"phrase":"miss the train"},{"phrase":"by train"},{"phrase":"train station"}]', NULL, '/treɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/train/train__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-1-08', 'ngsl-1', 'Thông dụng 1–500 · Bộ 8', 'New General Service List, thứ hạng 1–500', '#3da9fc', 'BookOpen', 8);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 1, 'possible', 'có thể; khả thi', 'adjective', '[{"en":"Could you please send me the report as soon as possible?","vi":"Bạn có thể gửi cho tôi bản báo cáo sớm nhất có thể không?"},{"en":"Is it possible to change my flight to Friday?","vi":"Có thể đổi chuyến bay của tôi sang thứ Sáu không?"},{"en":"Without your help, this project would not have been possible.","vi":"Nếu không có sự giúp đỡ của bạn, dự án này đã không thể thực hiện được."}]', '[{"phrase":"as soon as possible"},{"phrase":"if possible"},{"phrase":"possible solution"}]', NULL, '/ˈpɑːsəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/possi/possible__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 2, 'actually', 'thật ra; thực sự', 'adverb', '[{"en":"I thought the test would be hard, but it was actually easy.","vi":"Tôi tưởng bài kiểm tra sẽ khó, nhưng thật ra nó lại dễ."},{"en":"Nobody knows what actually happened at the party last night.","vi":"Không ai biết thực sự đã xảy ra chuyện gì ở bữa tiệc tối qua."},{"en":"Actually, I don''t think we have met before.","vi":"Thật ra, tôi không nghĩ là chúng ta đã gặp nhau trước đây."}]', '[{"phrase":"what actually happened"},{"phrase":"actually happen"}]', 'actually = thật ra, KHÔNG có nghĩa là "hiện nay" (currently)', '/ˈæktʃuəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/act/actua/actually__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 3, 'rather', 'khá; thà (… còn hơn); thay vì', 'adverb', '[{"en":"I''d rather stay home tonight than go out in the rain.","vi":"Tối nay tôi thà ở nhà còn hơn ra ngoài dưới trời mưa."},{"en":"The hotel room was rather small, but it was clean.","vi":"Phòng khách sạn khá nhỏ, nhưng sạch sẽ."},{"en":"Let''s take the train rather than drive into the city.","vi":"Chúng ta hãy đi tàu thay vì lái xe vào thành phố."}]', '[{"phrase":"would rather"},{"phrase":"rather than"},{"phrase":"rather difficult"}]', 'would rather + V nguyên mẫu; rather than = thay vì', '/ˈræðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rat/rathe/rather__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 4, 'view', 'quan điểm; quang cảnh, tầm nhìn', 'noun', '[{"en":"Our room had a beautiful view of the sea.","vi":"Phòng của chúng tôi có tầm nhìn ra biển rất đẹp."},{"en":"In my view, children should spend less time on their phones.","vi":"Theo quan điểm của tôi, trẻ em nên dành ít thời gian cho điện thoại hơn."},{"en":"We have different views on how to raise our kids.","vi":"Chúng tôi có quan điểm khác nhau về cách nuôi dạy con cái."}]', '[{"phrase":"point of view"},{"phrase":"in my view"},{"phrase":"beautiful view"}]', NULL, '/vjuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vie/view_/view__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 5, 'together', 'cùng nhau; với nhau', 'adverb', '[{"en":"My sister and I work together at the same hospital.","vi":"Tôi và chị gái cùng làm việc ở một bệnh viện."},{"en":"Why don''t we have dinner together this weekend?","vi":"Sao chúng ta không cùng nhau ăn tối vào cuối tuần này nhỉ?"},{"en":"Mix the flour and sugar together in a large bowl.","vi":"Trộn bột mì và đường với nhau trong một cái bát lớn."}]', '[{"phrase":"work together"},{"phrase":"get together"},{"phrase":"live together"}]', NULL, '/təˈɡeðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tog/toget/together__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 6, 'consider', 'cân nhắc, xem xét; coi là', 'verb', '[{"en":"We are considering moving to a bigger apartment.","vi":"Chúng tôi đang cân nhắc chuyển đến một căn hộ lớn hơn."},{"en":"Please consider all the options before you make a decision.","vi":"Hãy xem xét tất cả các lựa chọn trước khi đưa ra quyết định."},{"en":"Many people consider him the best teacher in our school.","vi":"Nhiều người coi thầy ấy là giáo viên giỏi nhất trường chúng tôi."}]', '[{"phrase":"consider the options"},{"phrase":"seriously consider"},{"phrase":"consider carefully"}]', 'consider + V-ing (consider moving)', '/kənˈsɪdər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsider__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 7, 'price', 'giá, giá cả', 'noun', '[{"en":"The price of fresh vegetables has gone up this month.","vi":"Giá rau tươi đã tăng trong tháng này."},{"en":"Excuse me, what is the price of this jacket?","vi":"Xin lỗi, chiếc áo khoác này giá bao nhiêu?"},{"en":"They sell good food at very reasonable prices.","vi":"Họ bán đồ ăn ngon với giá rất phải chăng."}]', '[{"phrase":"reasonable price"},{"phrase":"high price"},{"phrase":"full price"}]', NULL, '/praɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/price/price__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 8, 'parent', 'cha hoặc mẹ; bố mẹ; phụ huynh', 'noun', '[{"en":"My parents live in a small village near the coast.","vi":"Bố mẹ tôi sống ở một ngôi làng nhỏ gần bờ biển."},{"en":"She raised three children as a single parent.","vi":"Cô ấy là mẹ đơn thân nuôi ba đứa con."},{"en":"The teacher called a meeting with parents after school.","vi":"Giáo viên đã mời phụ huynh đến họp sau giờ học."}]', '[{"phrase":"single parent"},{"phrase":"working parents"},{"phrase":"new parents"}]', NULL, '/ˈperənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/paren/parent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 9, 'hard', 'khó; cứng; vất vả, khó khăn', 'adjective', '[{"en":"It''s hard to believe that summer is almost over.","vi":"Thật khó tin là mùa hè sắp hết rồi."},{"en":"This mattress is too hard for me to sleep on.","vi":"Tấm nệm này cứng quá, tôi nằm ngủ không được."},{"en":"It has been a hard year for our family.","vi":"Đây là một năm khó khăn đối với gia đình chúng tôi."}]', '[{"phrase":"hard to believe"},{"phrase":"hard time"},{"phrase":"hard work"}]', 'work hard (chăm chỉ) ≠ hardly (hầu như không)', '/hɑːrd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/har/hard_/hard__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 10, 'party', 'bữa tiệc, buổi tiệc', 'noun', '[{"en":"We''re having a birthday party for my son on Saturday.","vi":"Chúng tôi sẽ tổ chức tiệc sinh nhật cho con trai vào thứ Bảy."},{"en":"Are you going to the party after work tonight?","vi":"Tối nay bạn có đi dự tiệc sau giờ làm không?"},{"en":"Everyone had a great time at the party.","vi":"Mọi người đã rất vui ở bữa tiệc."}]', '[{"phrase":"birthday party"},{"phrase":"have a party"},{"phrase":"throw a party"}]', NULL, '/ˈpɑːrti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/party/party__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 11, 'local', '(thuộc) địa phương; gần nhà', 'adjective', '[{"en":"We buy our vegetables from the local market every morning.","vi":"Chúng tôi mua rau ở chợ gần nhà mỗi sáng."},{"en":"Many local people work in the hotels near the beach.","vi":"Nhiều người dân địa phương làm việc ở các khách sạn gần bãi biển."},{"en":"The accident was reported in the local newspaper.","vi":"Vụ tai nạn đã được đưa tin trên báo địa phương."}]', '[{"phrase":"local people"},{"phrase":"local market"},{"phrase":"local newspaper"},{"phrase":"local time"}]', NULL, '/ˈləʊkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loc/local/local__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 12, 'control', 'kiểm soát; điều khiển; kiềm chế', 'verb', '[{"en":"She couldn''t control her anger and started shouting.","vi":"Cô ấy không kiềm chế được cơn giận và bắt đầu la hét."},{"en":"You can control the lights in the house with your phone.","vi":"Bạn có thể điều khiển đèn trong nhà bằng điện thoại."},{"en":"Regular exercise can help you control your weight.","vi":"Tập thể dục đều đặn có thể giúp bạn kiểm soát cân nặng."}]', '[{"phrase":"control the situation"},{"phrase":"control costs"},{"phrase":"control your weight"}]', 'control – controlled – controlled (gấp đôi chữ l)', '/kənˈtrəʊl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontrol__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 13, 'already', 'đã … rồi; rồi', 'adverb', '[{"en":"I''ve already eaten, but thanks for asking.","vi":"Tôi ăn rồi, nhưng cảm ơn bạn đã hỏi."},{"en":"By the time we arrived, the movie had already started.","vi":"Lúc chúng tôi đến thì phim đã bắt đầu rồi."},{"en":"It''s only March, but it already feels like summer.","vi":"Mới tháng Ba mà trời đã như mùa hè rồi."}]', '[{"phrase":"already know"},{"phrase":"already started"},{"phrase":"already done"}]', 'already thường dùng trong câu khẳng định; câu phủ định dùng yet', '/ɔːlˈredi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alr/alrea/already__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 14, 'concern', 'mối lo ngại, sự lo lắng; mối quan tâm', 'noun', '[{"en":"Safety is our main concern when choosing a car.","vi":"An toàn là mối quan tâm hàng đầu của chúng tôi khi chọn xe."},{"en":"Parents have raised concerns about the new school rules.","vi":"Phụ huynh đã bày tỏ lo ngại về nội quy mới của trường."},{"en":"There is growing concern about air pollution in big cities.","vi":"Mối lo ngại về ô nhiễm không khí ở các thành phố lớn ngày càng tăng."}]', '[{"phrase":"main concern"},{"phrase":"raise concerns"},{"phrase":"growing concern"},{"phrase":"cause for concern"}]', NULL, '/kənˈsɜːrn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcern__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 15, 'product', 'sản phẩm', 'noun', '[{"en":"This shop sells only natural beauty products.","vi":"Cửa hàng này chỉ bán các sản phẩm làm đẹp tự nhiên."},{"en":"Our company is launching a new product next month.","vi":"Công ty chúng tôi sẽ ra mắt một sản phẩm mới vào tháng sau."},{"en":"If you''re not happy with the product, you can return it.","vi":"Nếu không hài lòng với sản phẩm, bạn có thể trả lại."}]', '[{"phrase":"new product"},{"phrase":"launch a product"},{"phrase":"beauty products"}]', NULL, '/ˈprɑːdʌkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/produ/product__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 16, 'lose', 'mất, làm mất; thua; giảm (cân)', 'verb', '[{"en":"I lost my keys somewhere on the way home.","vi":"Tôi đã làm mất chìa khóa ở đâu đó trên đường về nhà."},{"en":"Our team lost the match by two goals.","vi":"Đội chúng tôi đã thua trận với cách biệt hai bàn."},{"en":"He wants to lose weight before summer.","vi":"Anh ấy muốn giảm cân trước mùa hè."}]', '[{"phrase":"lose weight"},{"phrase":"lose a game"},{"phrase":"lose your job"}]', 'lose – lost – lost; lose (v) ≠ loose (adj: lỏng)', '/luːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/los/lose_/lose__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 17, 'story', 'câu chuyện; truyện', 'noun', '[{"en":"My grandmother used to tell me stories before bed.","vi":"Bà tôi thường kể chuyện cho tôi nghe trước khi đi ngủ."},{"en":"It''s a long story, so I''ll tell you later.","vi":"Chuyện dài lắm, để sau tôi kể cho bạn nghe."},{"en":"She has written several short stories for children.","vi":"Cô ấy đã viết một vài truyện ngắn cho trẻ em."}]', '[{"phrase":"tell a story"},{"phrase":"short story"},{"phrase":"long story"},{"phrase":"true story"}]', NULL, '/ˈstɔːri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/story/story__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 18, 'almost', 'gần như, hầu như; suýt', 'adverb', '[{"en":"Dinner is almost ready, so please wash your hands.","vi":"Bữa tối gần xong rồi, mọi người đi rửa tay nhé."},{"en":"I almost missed the bus this morning.","vi":"Sáng nay tôi suýt lỡ chuyến xe buýt."},{"en":"Almost everyone in my class has a smartphone.","vi":"Hầu như ai trong lớp tôi cũng có điện thoại thông minh."}]', '[{"phrase":"almost always"},{"phrase":"almost everyone"},{"phrase":"almost ready"}]', NULL, '/ˈɔːlməʊst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alm/almos/almost__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 19, 'continue', 'tiếp tục', 'verb', '[{"en":"After a short break, we continued our walk.","vi":"Sau khi nghỉ một lát, chúng tôi tiếp tục đi bộ."},{"en":"House prices in the city continue to rise every year.","vi":"Giá nhà ở thành phố tiếp tục tăng mỗi năm."},{"en":"If the rain continues, the game will be canceled.","vi":"Nếu trời tiếp tục mưa, trận đấu sẽ bị hủy."}]', '[{"phrase":"continue to rise"},{"phrase":"continue working"},{"phrase":"continue your studies"}]', 'continue + to V / V-ing', '/kənˈtɪnjuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontinue__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 20, 'stand', 'đứng; chịu đựng', 'verb', '[{"en":"We had to stand in line for an hour to buy tickets.","vi":"Chúng tôi phải đứng xếp hàng một tiếng để mua vé."},{"en":"Please stand up when the teacher comes in.","vi":"Hãy đứng dậy khi giáo viên bước vào."},{"en":"I can''t stand the noise from the construction site next door.","vi":"Tôi không chịu nổi tiếng ồn từ công trường bên cạnh."}]', '[{"phrase":"stand up"},{"phrase":"stand in line"},{"phrase":"can''t stand"}]', 'stand – stood – stood', '/stænd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stand/stand__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 21, 'whole', 'toàn bộ, cả', 'adjective', '[{"en":"I spent the whole day cleaning the house.","vi":"Tôi dành cả ngày để dọn dẹp nhà cửa."},{"en":"The whole family went to the beach for the weekend.","vi":"Cả gia đình đã đi biển vào cuối tuần."},{"en":"He ate the whole pizza by himself.","vi":"Anh ấy ăn hết cả cái bánh pizza một mình."}]', '[{"phrase":"the whole day"},{"phrase":"the whole family"},{"phrase":"the whole world"},{"phrase":"the whole time"}]', 'whole ≠ hole (cái lỗ), phát âm giống nhau', '/həʊl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/who/whole/whole__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 22, 'yet', 'chưa; vẫn chưa; tuy nhiên', 'adverb', '[{"en":"Have you finished your homework yet, or do you need more time?","vi":"Con đã làm xong bài tập chưa, hay cần thêm thời gian?"},{"en":"I haven''t heard back from the company yet.","vi":"Tôi vẫn chưa nhận được phản hồi từ công ty."},{"en":"The hotel was cheap, yet it was clean and comfortable.","vi":"Khách sạn rẻ, tuy vậy lại sạch sẽ và thoải mái."}]', '[{"phrase":"not yet"},{"phrase":"yet another"},{"phrase":"have yet to"}]', 'yet (chưa) thường dùng trong câu hỏi và câu phủ định', '/jet/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/yet/yet__/yet__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 23, 'rate', 'tỷ lệ; tốc độ; mức giá', 'noun', '[{"en":"The birth rate has fallen in many countries.","vi":"Tỷ lệ sinh đã giảm ở nhiều quốc gia."},{"en":"The city is growing at a fast rate.","vi":"Thành phố đang phát triển với tốc độ nhanh."},{"en":"The hotel offers special rates for students.","vi":"Khách sạn có mức giá ưu đãi cho sinh viên."}]', '[{"phrase":"birth rate"},{"phrase":"interest rate"},{"phrase":"exchange rate"},{"phrase":"heart rate"}]', NULL, '/reɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rat/rate_/rate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 24, 'care', 'quan tâm; chăm sóc', 'verb', '[{"en":"I don''t care what other people think of me.","vi":"Tôi không quan tâm người khác nghĩ gì về mình."},{"en":"She really cares about protecting the environment.","vi":"Cô ấy thực sự quan tâm đến việc bảo vệ môi trường."},{"en":"Nurses care for patients day and night.","vi":"Các y tá chăm sóc bệnh nhân cả ngày lẫn đêm."}]', '[{"phrase":"care about"},{"phrase":"care for"},{"phrase":"don''t care"}]', 'care about (quan tâm) · care for (chăm sóc)', '/ker/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/care_/care__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 25, 'expect', 'mong đợi; dự kiến; chờ (ai đến)', 'verb', '[{"en":"We expect the package to arrive by Friday.","vi":"Chúng tôi dự kiến gói hàng sẽ đến trước thứ Sáu."},{"en":"The trip cost much more than expected.","vi":"Chuyến đi tốn kém hơn nhiều so với dự kiến."},{"en":"Are you expecting any visitors this afternoon?","vi":"Chiều nay bạn có đang chờ khách nào không?"}]', '[{"phrase":"than expected"},{"phrase":"as expected"},{"phrase":"expect a baby"}]', NULL, '/ɪkˈspekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expec/expect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 26, 'effect', 'ảnh hưởng, tác động; tác dụng; hiệu lực', 'noun', '[{"en":"Too much sugar has a bad effect on your teeth.","vi":"Quá nhiều đường có ảnh hưởng xấu đến răng của bạn."},{"en":"This medicine may have some side effects.","vi":"Thuốc này có thể có một số tác dụng phụ."},{"en":"The new rules will take effect next month.","vi":"Các quy định mới sẽ có hiệu lực từ tháng sau."}]', '[{"phrase":"side effect"},{"phrase":"have an effect on"},{"phrase":"take effect"}]', 'effect (n) ≠ affect (v)', '/ɪˈfekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eff/effec/effect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 27, 'sort', 'loại, kiểu', 'noun', '[{"en":"What sort of music do you like?","vi":"Bạn thích loại nhạc nào?"},{"en":"This is the sort of place I''d love to live in.","vi":"Đây chính là kiểu nơi tôi rất muốn được sống."},{"en":"The shop sells all sorts of things for the kitchen.","vi":"Cửa hàng bán đủ loại đồ dùng cho nhà bếp."}]', '[{"phrase":"what sort of"},{"phrase":"all sorts of"},{"phrase":"sort of"}]', 'sort of (thân mật) = hơi, kiểu như', '/sɔːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sor/sort_/sort__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 28, 'ever', 'từng, đã bao giờ; mãi mãi', 'adverb', '[{"en":"Have you ever been abroad on your own?","vi":"Bạn đã bao giờ tự đi nước ngoài một mình chưa?"},{"en":"This is the best coffee I''ve ever had.","vi":"Đây là ly cà phê ngon nhất tôi từng uống."},{"en":"They got married and lived happily ever after.","vi":"Họ kết hôn và sống hạnh phúc mãi mãi về sau."}]', '[{"phrase":"have you ever"},{"phrase":"ever since"},{"phrase":"than ever"}]', NULL, '/ˈevər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/ever_/ever__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 29, 'anything', 'bất cứ thứ gì; (câu hỏi, phủ định) gì', 'pronoun', '[{"en":"Is there anything else I can help you with?","vi":"Còn gì khác tôi có thể giúp bạn không?"},{"en":"I didn''t eat anything for breakfast this morning.","vi":"Sáng nay tôi không ăn sáng gì cả."},{"en":"You can order anything you like from the menu.","vi":"Bạn có thể gọi bất cứ món gì bạn thích trong thực đơn."}]', '[{"phrase":"anything else"},{"phrase":"do anything"},{"phrase":"anything at all"}]', 'câu hỏi/phủ định: gì; câu khẳng định: bất cứ thứ gì', '/ˈeniθɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/any/anyth/anything__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-08', 30, 'cause', 'gây ra, làm cho', 'verb', '[{"en":"Heavy rain caused flooding in several parts of the city.","vi":"Mưa lớn đã gây ngập lụt ở nhiều khu vực trong thành phố."},{"en":"I''m sorry for causing so much trouble.","vi":"Tôi xin lỗi vì đã gây ra nhiều rắc rối như vậy."},{"en":"Smoking can cause serious health problems later in life.","vi":"Hút thuốc có thể gây ra các vấn đề sức khỏe nghiêm trọng về sau."}]', '[{"phrase":"cause problems"},{"phrase":"cause damage"},{"phrase":"cause trouble"}]', NULL, '/kɔːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cau/cause/cause__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-1-09', 'ngsl-1', 'Thông dụng 1–500 · Bộ 9', 'New General Service List, thứ hạng 1–500', '#3da9fc', 'BookOpen', 9);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 1, 'fall', 'rơi; ngã; giảm', 'verb', '[{"en":"Be careful on the stairs so you don''t fall.","vi":"Cẩn thận trên cầu thang kẻo bạn bị ngã."},{"en":"A lot of leaves fell from the trees last night.","vi":"Tối qua rất nhiều lá rơi khỏi cây."},{"en":"House prices have fallen a little this year.","vi":"Giá nhà năm nay đã giảm một chút."}]', '[{"phrase":"fall asleep"},{"phrase":"fall down"},{"phrase":"fall off"},{"phrase":"prices fall"}]', 'fall – fell – fallen', '/fɔːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fal/fall_/fall__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 2, 'deal', 'thỏa thuận; giao dịch; món hời', 'noun', '[{"en":"We finally made a deal with the new supplier.","vi":"Cuối cùng chúng tôi đã đạt được thỏa thuận với nhà cung cấp mới."},{"en":"I got a really good deal on this laptop.","vi":"Tôi mua được chiếc máy tính xách tay này với giá rất hời."},{"en":"The two companies signed a business deal last week.","vi":"Tuần trước hai công ty đã ký một thỏa thuận kinh doanh."}]', '[{"phrase":"make a deal"},{"phrase":"good deal"},{"phrase":"business deal"},{"phrase":"sign a deal"}]', 'a great deal of = rất nhiều', '/diːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dea/deal_/deal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 3, 'water', 'nước', 'noun', '[{"en":"Could I have a glass of water, please?","vi":"Cho tôi xin một cốc nước được không?"},{"en":"You should drink plenty of water on hot days.","vi":"Bạn nên uống nhiều nước vào những ngày nóng."},{"en":"The water in the lake was too cold for swimming.","vi":"Nước hồ quá lạnh để bơi."}]', '[{"phrase":"glass of water"},{"phrase":"drink water"},{"phrase":"hot water"},{"phrase":"cold water"}]', 'không đếm được', '/ˈwɔːtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wat/water/water__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 4, 'send', 'gửi', 'verb', '[{"en":"I''ll send you the photos from the trip tonight.","vi":"Tối nay tôi sẽ gửi cho bạn ảnh chuyến đi."},{"en":"She sent a birthday card to her grandmother.","vi":"Cô ấy đã gửi một tấm thiếp sinh nhật cho bà."},{"en":"Please send me an email when you arrive.","vi":"Khi nào đến nơi thì gửi email cho tôi nhé."}]', '[{"phrase":"send an email"},{"phrase":"send a message"},{"phrase":"send a letter"}]', 'send – sent – sent', '/send/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sen/send_/send__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 5, 'allow', 'cho phép', 'verb', '[{"en":"My parents didn''t allow me to stay out late.","vi":"Bố mẹ không cho phép tôi đi chơi về khuya."},{"en":"Smoking is not allowed inside the building.","vi":"Không được phép hút thuốc trong tòa nhà."},{"en":"The new app allows you to pay with your phone.","vi":"Ứng dụng mới cho phép bạn thanh toán bằng điện thoại."}]', '[{"phrase":"allow someone to"},{"phrase":"be allowed to"},{"phrase":"not allowed"}]', 'allow sb to do sth', '/əˈlaʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/all/allow/allow__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 6, 'soon', 'sớm; chẳng bao lâu nữa', 'adverb', '[{"en":"Dinner will be ready soon, so please wash your hands.","vi":"Bữa tối sắp xong rồi, nên đi rửa tay đi nhé."},{"en":"I really hope you feel better soon.","vi":"Mình thật sự mong bạn sớm khỏe lại."},{"en":"We left soon after the movie ended.","vi":"Chúng tôi ra về ngay sau khi phim kết thúc."}]', '[{"phrase":"as soon as possible"},{"phrase":"see you soon"},{"phrase":"soon after"}]', NULL, '/suːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/soo/soon_/soon__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 7, 'watch', 'xem; theo dõi; trông chừng', 'verb', '[{"en":"We watched a movie together after dinner.","vi":"Sau bữa tối chúng tôi cùng nhau xem một bộ phim."},{"en":"The kids love watching the birds in the garden.","vi":"Bọn trẻ rất thích ngắm chim trong vườn."},{"en":"Could you watch my bag while I buy a ticket?","vi":"Bạn trông giúp túi của tôi trong lúc tôi đi mua vé được không?"}]', '[{"phrase":"watch TV"},{"phrase":"watch a movie"},{"phrase":"watch carefully"}]', NULL, '/wɑːtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wat/watch/watch__us_6.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 8, 'base', 'dựa vào; đặt trụ sở', 'verb', '[{"en":"The movie is based on a true story.","vi":"Bộ phim dựa trên một câu chuyện có thật."},{"en":"Our company is based in a small town near the coast.","vi":"Công ty chúng tôi đặt trụ sở ở một thị trấn nhỏ gần bờ biển."},{"en":"She based her decision on what her customers wanted.","vi":"Cô ấy đưa ra quyết định dựa vào những gì khách hàng muốn."}]', '[{"phrase":"based on"},{"phrase":"be based in"},{"phrase":"base a decision on"}]', 'base sth on sth; be based in + nơi chốn', '/beɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bas/base_/base__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 9, 'probably', 'có lẽ; chắc là', 'adverb', '[{"en":"It will probably rain this afternoon, so take an umbrella.","vi":"Có lẽ chiều nay trời sẽ mưa, nên hãy mang theo ô."},{"en":"She''s probably still at work right now.","vi":"Giờ này chắc cô ấy vẫn đang ở chỗ làm."},{"en":"That was probably the best meal I''ve ever had.","vi":"Đó có lẽ là bữa ăn ngon nhất tôi từng ăn."}]', '[{"phrase":"will probably"},{"phrase":"most probably"},{"phrase":"probably not"}]', NULL, '/ˈprɑːbəbli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proba/probably__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 10, 'suggest', 'gợi ý; đề nghị; cho thấy', 'verb', '[{"en":"My friend suggested a good restaurant near the station.","vi":"Bạn tôi đã gợi ý một nhà hàng ngon gần nhà ga."},{"en":"I suggest leaving early to avoid the traffic.","vi":"Tôi đề nghị đi sớm để tránh kẹt xe."},{"en":"The results suggest that the plan is working.","vi":"Kết quả cho thấy kế hoạch đang có hiệu quả."}]', '[{"phrase":"suggest an idea"},{"phrase":"strongly suggest"},{"phrase":"suggest that"}]', 'suggest + V-ing / suggest that…; không dùng suggest sb to do', '/səˈdʒest/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sug/sugge/suggest__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 11, 'past', 'quá khứ', 'noun', '[{"en":"In the past, people wrote letters instead of emails.","vi":"Ngày xưa, người ta viết thư tay thay vì gửi email."},{"en":"He doesn''t like to talk about his past.","vi":"Anh ấy không thích nói về quá khứ của mình."},{"en":"Let''s forget the past and start again.","vi":"Hãy quên quá khứ đi và bắt đầu lại."}]', '[{"phrase":"in the past"},{"phrase":"the recent past"},{"phrase":"forget the past"}]', NULL, '/pæst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pas/past_/past__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 12, 'power', 'quyền lực; năng lượng; điện', 'noun', '[{"en":"Parents have a lot of power over their young children.","vi":"Cha mẹ có nhiều quyền lực đối với con cái còn nhỏ."},{"en":"More homes in the area now use solar power.","vi":"Giờ đây ngày càng nhiều nhà trong khu vực dùng năng lượng mặt trời."},{"en":"The power went out during the storm last night.","vi":"Tối qua bị mất điện trong lúc có bão."}]', '[{"phrase":"solar power"},{"phrase":"power outage"},{"phrase":"have the power to"}]', NULL, '/ˈpaʊər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pow/power/power__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 13, 'test', 'bài kiểm tra; kỳ thi; xét nghiệm', 'noun', '[{"en":"I have a math test tomorrow morning.","vi":"Sáng mai tôi có bài kiểm tra toán."},{"en":"She passed her driving test on the first try.","vi":"Cô ấy đã thi đỗ bằng lái xe ngay lần đầu."},{"en":"The doctor wants me to have a blood test.","vi":"Bác sĩ muốn tôi đi xét nghiệm máu."}]', '[{"phrase":"take a test"},{"phrase":"pass a test"},{"phrase":"driving test"},{"phrase":"blood test"}]', NULL, '/test/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tes/test_/test__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 14, 'visit', 'thăm; đến thăm; tham quan', 'verb', '[{"en":"We visit my grandparents every Sunday.","vi":"Chủ nhật nào chúng tôi cũng đi thăm ông bà."},{"en":"Millions of tourists visit the city each year.","vi":"Mỗi năm có hàng triệu du khách đến tham quan thành phố."},{"en":"Have you ever visited the old part of town?","vi":"Bạn đã từng đến khu phố cổ chưa?"}]', '[{"phrase":"visit a friend"},{"phrase":"visit a museum"},{"phrase":"visit the doctor"}]', NULL, '/ˈvɪzɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visit/visit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 15, 'center', 'trung tâm; chính giữa', 'noun', '[{"en":"Our hotel is right in the city center.","vi":"Khách sạn của chúng tôi nằm ngay trung tâm thành phố."},{"en":"There''s a big shopping center near my office.","vi":"Gần văn phòng tôi có một trung tâm mua sắm lớn."},{"en":"Put the vase in the center of the table.","vi":"Đặt cái bình ở chính giữa bàn nhé."}]', '[{"phrase":"city center"},{"phrase":"shopping center"},{"phrase":"in the center of"}]', 'Mỹ: center · Anh: centre', '/ˈsentər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cen/centr/centre__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 16, 'grow', 'lớn lên; trồng; tăng lên', 'verb', '[{"en":"Children grow so fast at this age.","vi":"Ở tuổi này trẻ con lớn nhanh lắm."},{"en":"My mother grows tomatoes in the backyard.","vi":"Mẹ tôi trồng cà chua ở sân sau."},{"en":"The number of online shoppers has grown quickly.","vi":"Số người mua sắm trực tuyến đã tăng lên nhanh chóng."}]', '[{"phrase":"grow up"},{"phrase":"grow vegetables"},{"phrase":"grow quickly"}]', 'grow – grew – grown', '/ɡrəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gro/grow_/grow__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 17, 'nothing', 'không có gì; không cái gì', 'pronoun', '[{"en":"There''s nothing in the fridge, so let''s order food.","vi":"Tủ lạnh chẳng có gì, nên mình gọi đồ ăn đi."},{"en":"I have nothing to do this weekend.","vi":"Cuối tuần này tôi không có việc gì làm."},{"en":"She said nothing about the problem at the meeting.","vi":"Trong cuộc họp cô ấy không nói gì về vấn đề đó."}]', '[{"phrase":"nothing else"},{"phrase":"nothing special"},{"phrase":"have nothing to do"}]', NULL, '/ˈnʌθɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/not/nothi/nothing__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 18, 'return', 'trở về; trả lại', 'verb', '[{"en":"He returned home after three years abroad.","vi":"Anh ấy trở về nhà sau ba năm ở nước ngoài."},{"en":"Please return the books to the library by Friday.","vi":"Vui lòng trả sách cho thư viện trước thứ Sáu."},{"en":"I''ll return your call as soon as I can.","vi":"Tôi sẽ gọi lại cho bạn ngay khi có thể."}]', '[{"phrase":"return home"},{"phrase":"return a call"},{"phrase":"return from"}]', 'không nói return back', '/rɪˈtɜːrn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ret/retur/return__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 19, 'mother', 'mẹ', 'noun', '[{"en":"My mother taught me how to cook.","vi":"Mẹ đã dạy tôi nấu ăn."},{"en":"She became a mother at the age of thirty.","vi":"Cô ấy làm mẹ ở tuổi ba mươi."},{"en":"Does your mother still live in the same house?","vi":"Mẹ bạn vẫn sống ở ngôi nhà cũ chứ?"}]', '[{"phrase":"young mother"},{"phrase":"working mother"},{"phrase":"mother and father"}]', NULL, '/ˈmʌðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mot/mothe/mother__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 20, 'walk', 'đi bộ; dắt đi dạo', 'verb', '[{"en":"I usually walk to work when the weather is nice.","vi":"Khi trời đẹp tôi thường đi bộ đi làm."},{"en":"They walked along the beach for an hour.","vi":"Họ đi bộ dọc bãi biển suốt một tiếng."},{"en":"Can you walk the dog before dinner?","vi":"Bạn dắt chó đi dạo trước bữa tối được không?"}]', '[{"phrase":"walk home"},{"phrase":"walk to work"},{"phrase":"walk the dog"}]', NULL, '/wɔːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wal/walk_/walk__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 21, 'matter', 'quan trọng; có ý nghĩa', 'verb', '[{"en":"It doesn''t matter if you''re a few minutes late.","vi":"Bạn đến trễ vài phút cũng không sao."},{"en":"Your health matters more than your job.","vi":"Sức khỏe của bạn quan trọng hơn công việc."},{"en":"Does it really matter what other people think?","vi":"Người khác nghĩ gì thì có thực sự quan trọng không?"}]', '[{"phrase":"it doesn''t matter"},{"phrase":"really matter"},{"phrase":"matter to someone"}]', 'What''s the matter? = Có chuyện gì vậy?', '/ˈmætər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mat/matte/matter__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 22, 'mind', 'tâm trí; đầu óc; ý định', 'noun', '[{"en":"I was going to buy the red one, but I changed my mind.","vi":"Tôi định mua cái màu đỏ nhưng rồi đổi ý."},{"en":"A short walk helps me clear my mind.","vi":"Đi bộ một chút giúp đầu óc tôi thư thái."},{"en":"Keep in mind that the store closes early today.","vi":"Hãy nhớ rằng hôm nay cửa hàng đóng cửa sớm."}]', '[{"phrase":"change your mind"},{"phrase":"make up your mind"},{"phrase":"keep in mind"}]', 'Do you mind…? = Bạn có phiền…?', '/maɪnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/mind_/mind__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 23, 'value', 'giá trị', 'noun', '[{"en":"The value of the house has doubled in ten years.","vi":"Giá trị căn nhà đã tăng gấp đôi trong mười năm."},{"en":"This old watch has great value to my family.","vi":"Chiếc đồng hồ cũ này rất có giá trị với gia đình tôi."},{"en":"Parents try to teach their children good values.","vi":"Cha mẹ cố gắng dạy con những giá trị tốt đẹp."}]', '[{"phrase":"the value of"},{"phrase":"great value"},{"phrase":"market value"}]', NULL, '/ˈvæljuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/val/value/value__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 24, 'office', 'văn phòng', 'noun', '[{"en":"I''ll be at the office until six today.","vi":"Hôm nay tôi ở văn phòng đến sáu giờ."},{"en":"Our office is on the fifth floor.","vi":"Văn phòng của chúng tôi ở tầng năm."},{"en":"She works in a small office downtown.","vi":"Cô ấy làm việc ở một văn phòng nhỏ trong trung tâm thành phố."}]', '[{"phrase":"office building"},{"phrase":"head office"},{"phrase":"at the office"}]', NULL, '/ˈɑːfɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/off/offic/office__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 25, 'record', 'hồ sơ; bản ghi chép; kỷ lục', 'noun', '[{"en":"The hospital keeps records of every patient.","vi":"Bệnh viện lưu hồ sơ của mọi bệnh nhân."},{"en":"Please keep a record of how much you spend.","vi":"Hãy ghi chép lại số tiền bạn đã tiêu."},{"en":"She broke the school record for the long jump.","vi":"Cô ấy đã phá kỷ lục nhảy xa của trường."}]', '[{"phrase":"keep a record"},{"phrase":"break a record"},{"phrase":"medical records"},{"phrase":"world record"}]', 'danh từ nhấn âm đầu (RE-cord); động từ nhấn âm sau (re-CORD)', '/ˈrekərd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recor/record__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 26, 'stay', 'ở lại; lưu lại; giữ', 'verb', '[{"en":"I stayed at home all day because of the rain.","vi":"Tôi ở nhà cả ngày vì trời mưa."},{"en":"We stayed in a small hotel near the beach.","vi":"Chúng tôi ở một khách sạn nhỏ gần bãi biển."},{"en":"Try to stay calm during the exam.","vi":"Hãy cố gắng giữ bình tĩnh trong lúc thi."}]', '[{"phrase":"stay at home"},{"phrase":"stay in a hotel"},{"phrase":"stay calm"},{"phrase":"stay up late"}]', NULL, '/steɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stay_/stay__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 27, 'force', 'buộc; ép', 'verb', '[{"en":"Heavy rain forced us to cancel the picnic.","vi":"Mưa to buộc chúng tôi phải hủy buổi dã ngoại."},{"en":"Nobody forced you to take this job.","vi":"Không ai ép bạn nhận công việc này cả."},{"en":"The shop was forced to close after ten years.","vi":"Cửa hàng buộc phải đóng cửa sau mười năm."}]', '[{"phrase":"force someone to"},{"phrase":"be forced to"}]', 'force sb to do sth', '/fɔːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/force/force__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 28, 'stop', 'dừng; ngừng', 'verb', '[{"en":"The bus stops right in front of my house.","vi":"Xe buýt dừng ngay trước nhà tôi."},{"en":"Please stop talking and listen to me.","vi":"Làm ơn ngừng nói chuyện và nghe tôi nói."},{"en":"It finally stopped raining at around midnight.","vi":"Khoảng nửa đêm thì trời cuối cùng cũng tạnh mưa."}]', '[{"phrase":"stop talking"},{"phrase":"stop working"},{"phrase":"stop raining"}]', 'stop + V-ing = ngừng làm; stop + to V = dừng lại để làm', '/stɑːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/stop_/stop__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 29, 'several', 'vài; một số', 'determiner', '[{"en":"I''ve been to that café several times.","vi":"Tôi đã đến quán cà phê đó vài lần."},{"en":"Several students were late for class this morning.","vi":"Sáng nay có một số học sinh đi học muộn."},{"en":"She lived in Japan for several years.","vi":"Cô ấy đã sống ở Nhật Bản vài năm."}]', '[{"phrase":"several times"},{"phrase":"several years"},{"phrase":"several people"}]', NULL, '/ˈsevrəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sev/sever/several__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-09', 30, 'light', 'ánh sáng; đèn', 'noun', '[{"en":"Don''t forget to turn off the lights when you leave.","vi":"Đừng quên tắt đèn khi ra ngoài."},{"en":"This room gets a lot of light in the morning.","vi":"Buổi sáng căn phòng này có rất nhiều ánh sáng."},{"en":"Turn left at the next traffic light.","vi":"Rẽ trái ở cột đèn giao thông tiếp theo."}]', '[{"phrase":"turn on the light"},{"phrase":"turn off the light"},{"phrase":"bright light"},{"phrase":"traffic light"}]', NULL, '/laɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lig/light/light__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-1-10', 'ngsl-1', 'Thông dụng 1–500 · Bộ 10', 'New General Service List, thứ hạng 1–500', '#3da9fc', 'BookOpen', 10);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 1, 'develop', 'phát triển; xây dựng, tạo ra', 'verb', '[{"en":"Children develop very quickly in their first few years.","vi":"Trẻ em phát triển rất nhanh trong vài năm đầu đời."},{"en":"Our team is developing a new app for students.","vi":"Nhóm chúng tôi đang xây dựng một ứng dụng mới cho sinh viên."},{"en":"She developed a strong interest in music at school.","vi":"Cô ấy dần có niềm đam mê lớn với âm nhạc khi còn đi học."}]', '[{"phrase":"develop skills"},{"phrase":"develop a plan"},{"phrase":"develop a product"}]', NULL, '/dɪˈveləp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dev/devel/develop__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 2, 'remember', 'nhớ; ghi nhớ', 'verb', '[{"en":"Do you remember the name of that restaurant?","vi":"Bạn có nhớ tên nhà hàng đó không?"},{"en":"I can''t remember where I put my keys.","vi":"Tôi không nhớ mình để chìa khóa ở đâu."},{"en":"Remember to lock the door when you leave.","vi":"Nhớ khóa cửa khi bạn ra ngoài nhé."}]', '[{"phrase":"remember the name"},{"phrase":"can''t remember"},{"phrase":"remember clearly"}]', 'remember to do (nhớ để làm) ≠ remember doing (nhớ đã làm)', '/rɪˈmembər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remem/remember__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 3, 'bit', 'một chút; mẩu, miếng nhỏ', 'noun', '[{"en":"I''m a bit tired after the long trip.","vi":"Tôi hơi mệt một chút sau chuyến đi dài."},{"en":"Let''s wait a bit longer for the rain to stop.","vi":"Mình đợi thêm một chút cho mưa tạnh đã."},{"en":"She gave the dog a bit of her sandwich.","vi":"Cô ấy cho con chó một mẩu bánh mì kẹp của mình."}]', '[{"phrase":"a bit"},{"phrase":"a little bit"},{"phrase":"a bit of"},{"phrase":"bit by bit"}]', NULL, '/bɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bit/bit__/bit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 4, 'share', 'chia sẻ; dùng chung', 'verb', '[{"en":"I share a small apartment with two friends.","vi":"Tôi ở chung một căn hộ nhỏ với hai người bạn."},{"en":"Thanks for sharing your ideas at the meeting.","vi":"Cảm ơn bạn đã chia sẻ ý tưởng trong cuộc họp."},{"en":"We shared a pizza and watched a movie.","vi":"Chúng tôi ăn chung một chiếc pizza và xem phim."}]', '[{"phrase":"share a room"},{"phrase":"share ideas"},{"phrase":"share information"},{"phrase":"share with"}]', NULL, '/ʃer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sha/share/share__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 5, 'real', 'thật; thực sự', 'adjective', '[{"en":"Is that a real diamond or just glass?","vi":"Đó là kim cương thật hay chỉ là thủy tinh?"},{"en":"The real problem is that we don''t have enough time.","vi":"Vấn đề thực sự là chúng ta không có đủ thời gian."},{"en":"He looks much younger in real life than on TV.","vi":"Ngoài đời thật, anh ấy trông trẻ hơn nhiều so với trên TV."}]', '[{"phrase":"real life"},{"phrase":"the real world"},{"phrase":"real problem"}]', NULL, '/ˈriːəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/real_/real__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 6, 'answer', 'câu trả lời; đáp án', 'noun', '[{"en":"I asked him a question, but he didn''t give an answer.","vi":"Tôi hỏi anh ấy một câu, nhưng anh ấy không trả lời."},{"en":"Check your answers before you hand in the test.","vi":"Hãy kiểm tra lại các câu trả lời trước khi nộp bài kiểm tra."},{"en":"Nobody knows the answer to this problem yet.","vi":"Chưa ai biết lời giải cho vấn đề này."}]', '[{"phrase":"the right answer"},{"phrase":"give an answer"},{"phrase":"answer to"}]', NULL, '/ˈænsər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ans/answe/answer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 7, 'sit', 'ngồi', 'verb', '[{"en":"Please sit down and make yourself comfortable.","vi":"Mời bạn ngồi xuống và cứ tự nhiên nhé."},{"en":"We sat by the window and watched the rain.","vi":"Chúng tôi ngồi cạnh cửa sổ và ngắm mưa."},{"en":"My grandfather likes sitting in the garden after lunch.","vi":"Ông tôi thích ngồi ngoài vườn sau bữa trưa."}]', '[{"phrase":"sit down"},{"phrase":"sit next to"},{"phrase":"sit by the window"}]', 'sit – sat – sat', '/sɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sit/sit__/sit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 8, 'figure', 'con số, số liệu; nhân vật; bóng người, dáng người', 'noun', '[{"en":"The sales figures for this month look much better.","vi":"Số liệu bán hàng tháng này trông khả quan hơn nhiều."},{"en":"She is an important figure in the local art world.","vi":"Bà ấy là một nhân vật quan trọng trong giới nghệ thuật địa phương."},{"en":"I saw a dark figure standing near the gate.","vi":"Tôi thấy một bóng người đứng gần cổng."}]', '[{"phrase":"sales figures"},{"phrase":"key figure"},{"phrase":"official figures"}]', NULL, '/ˈfɪɡjər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fig/figur/figure__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 9, 'letter', 'lá thư; chữ cái', 'noun', '[{"en":"I got a letter from my old teacher today.","vi":"Hôm nay tôi nhận được thư của thầy giáo cũ."},{"en":"Please write your name in capital letters.","vi":"Vui lòng viết tên của bạn bằng chữ in hoa."},{"en":"My grandmother still writes letters to her friends.","vi":"Bà tôi vẫn viết thư cho bạn bè."}]', '[{"phrase":"write a letter"},{"phrase":"receive a letter"},{"phrase":"capital letter"}]', NULL, '/ˈletər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/let/lette/letter__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 10, 'decide', 'quyết định', 'verb', '[{"en":"We decided to stay home because of the storm.","vi":"Chúng tôi quyết định ở nhà vì cơn bão."},{"en":"Have you decided what to order yet?","vi":"Bạn đã quyết định gọi món gì chưa?"},{"en":"It''s hard to decide between these two jobs.","vi":"Thật khó để quyết định chọn giữa hai công việc này."}]', '[{"phrase":"decide to"},{"phrase":"decide between"},{"phrase":"finally decide"}]', 'decide to do something', '/dɪˈsaɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decid/decide__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 11, 'language', 'ngôn ngữ', 'noun', '[{"en":"How many languages can your sister speak?","vi":"Chị của bạn nói được bao nhiêu ngôn ngữ?"},{"en":"English is the main language used at our company.","vi":"Tiếng Anh là ngôn ngữ chính được dùng ở công ty chúng tôi."},{"en":"Body language can tell you a lot about someone''s feelings.","vi":"Ngôn ngữ cơ thể có thể cho bạn biết nhiều về cảm xúc của một người."}]', '[{"phrase":"foreign language"},{"phrase":"body language"},{"phrase":"first language"},{"phrase":"speak a language"}]', NULL, '/ˈlæŋɡwɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lan/langu/language__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 12, 'subject', 'môn học; chủ đề', 'noun', '[{"en":"Math was always my favorite subject at school.","vi":"Toán luôn là môn học yêu thích của tôi ở trường."},{"en":"Let''s change the subject and talk about something else.","vi":"Mình đổi chủ đề và nói chuyện khác đi."},{"en":"She has written several books on the subject of health.","vi":"Cô ấy đã viết vài cuốn sách về chủ đề sức khỏe."}]', '[{"phrase":"favorite subject"},{"phrase":"change the subject"},{"phrase":"on the subject of"}]', NULL, '/ˈsʌbdʒɪkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subje/subject__us_4_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 13, 'class', 'lớp học; buổi học', 'noun', '[{"en":"There are thirty students in my English class.","vi":"Lớp tiếng Anh của tôi có ba mươi học sinh."},{"en":"I have a yoga class every Tuesday evening.","vi":"Tôi có buổi học yoga vào mỗi tối thứ Ba."},{"en":"He missed class yesterday because he was sick.","vi":"Hôm qua anh ấy nghỉ học vì bị ốm."}]', '[{"phrase":"take a class"},{"phrase":"miss class"},{"phrase":"in class"}]', NULL, '/klæs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/class/class__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 14, 'development', 'sự phát triển', 'noun', '[{"en":"Sleep is very important for a child''s development.","vi":"Giấc ngủ rất quan trọng đối với sự phát triển của trẻ."},{"en":"The development of the new software took two years.","vi":"Việc phát triển phần mềm mới mất hai năm."},{"en":"Our company spends a lot on research and development.","vi":"Công ty chúng tôi chi nhiều tiền cho nghiên cứu và phát triển."}]', '[{"phrase":"economic development"},{"phrase":"child development"},{"phrase":"research and development"}]', NULL, '/dɪˈveləpmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dev/devel/development__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 15, 'town', 'thị trấn; thành phố, phố', 'noun', '[{"en":"I grew up in a small town near the sea.","vi":"Tôi lớn lên ở một thị trấn nhỏ gần biển."},{"en":"We''re going into town to do some shopping.","vi":"Chúng tôi sẽ ra phố mua sắm một chút."},{"en":"The whole town came out to watch the parade.","vi":"Cả thị trấn kéo ra xem diễu hành."}]', '[{"phrase":"small town"},{"phrase":"go into town"},{"phrase":"town center"}]', NULL, '/taʊn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tow/town_/town__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 16, 'half', 'một nửa', 'noun', '[{"en":"I''ve only read half of the book so far.","vi":"Đến giờ tôi mới đọc được một nửa cuốn sách."},{"en":"Cut the apple in half and share it with your brother.","vi":"Hãy cắt quả táo làm đôi và chia cho em trai con."},{"en":"We waited for half an hour at the station.","vi":"Chúng tôi đã đợi nửa tiếng ở nhà ga."}]', '[{"phrase":"half an hour"},{"phrase":"in half"},{"phrase":"half of"}]', 'số nhiều: halves', '/hæf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hal/half_/half__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 17, 'minute', 'phút; một lát', 'noun', '[{"en":"The next train leaves in about ten minutes.","vi":"Chuyến tàu tiếp theo sẽ khởi hành trong khoảng mười phút nữa."},{"en":"Can you wait a minute while I get my coat?","vi":"Bạn đợi một lát để tôi lấy áo khoác được không?"},{"en":"I walk for thirty minutes every morning.","vi":"Mỗi sáng tôi đi bộ ba mươi phút."}]', '[{"phrase":"wait a minute"},{"phrase":"just a minute"},{"phrase":"last minute"}]', NULL, '/ˈmɪnɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minut/minute__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 18, 'food', 'thức ăn, đồ ăn', 'noun', '[{"en":"We need to buy some food for the weekend.","vi":"Chúng ta cần mua ít đồ ăn cho cuối tuần."},{"en":"Street food in this city is cheap and delicious.","vi":"Đồ ăn đường phố ở thành phố này vừa rẻ vừa ngon."},{"en":"Healthy food doesn''t have to be expensive.","vi":"Đồ ăn lành mạnh không nhất thiết phải đắt."}]', '[{"phrase":"fast food"},{"phrase":"healthy food"},{"phrase":"street food"},{"phrase":"spicy food"}]', NULL, '/fuːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/foo/food_/food__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 19, 'break', 'làm vỡ, làm gãy; vi phạm (luật, lời hứa)', 'verb', '[{"en":"Be careful not to break those glasses.","vi":"Cẩn thận đừng làm vỡ mấy cái ly đó."},{"en":"He broke his arm when he fell off his bike.","vi":"Anh ấy bị gãy tay khi ngã xe đạp."},{"en":"You promised to call, so please don''t break your promise.","vi":"Bạn đã hứa sẽ gọi, nên đừng thất hứa nhé."}]', '[{"phrase":"break a promise"},{"phrase":"break the rules"},{"phrase":"break the law"},{"phrase":"break a window"}]', 'break – broke – broken', '/breɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bre/break/break__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 20, 'clear', 'rõ ràng; trong, quang đãng', 'adjective', '[{"en":"Are the instructions clear, or should I explain again?","vi":"Hướng dẫn đã rõ chưa, hay tôi nên giải thích lại?"},{"en":"It''s clear that she really enjoys her job.","vi":"Rõ ràng là cô ấy rất thích công việc của mình."},{"en":"On a clear day, you can see the mountains from here.","vi":"Vào ngày trời quang, bạn có thể nhìn thấy núi từ đây."}]', '[{"phrase":"make it clear"},{"phrase":"clear instructions"},{"phrase":"clear sky"},{"phrase":"perfectly clear"}]', NULL, '/klɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cle/clear/clear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 21, 'future', 'tương lai', 'noun', '[{"en":"Nobody knows what will happen in the future.","vi":"Không ai biết điều gì sẽ xảy ra trong tương lai."},{"en":"What are your plans for the future?","vi":"Bạn có kế hoạch gì cho tương lai?"},{"en":"They are saving money for their children''s future.","vi":"Họ đang tiết kiệm tiền cho tương lai của con cái."}]', '[{"phrase":"in the future"},{"phrase":"the near future"},{"phrase":"plans for the future"},{"phrase":"bright future"}]', NULL, '/ˈfjuːtʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fut/futur/future__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 22, 'either', 'hoặc (either … or); cũng (không)', 'conjunction', '[{"en":"You can pay either by cash or by card.","vi":"Bạn có thể trả bằng tiền mặt hoặc bằng thẻ."},{"en":"We can meet either on Friday or on Saturday.","vi":"Chúng ta có thể gặp nhau vào thứ Sáu hoặc thứ Bảy."},{"en":"I don''t like coffee, and my wife doesn''t either.","vi":"Tôi không thích cà phê, và vợ tôi cũng không."}]', '[{"phrase":"either … or"},{"phrase":"not … either"},{"phrase":"either way"},{"phrase":"either side"}]', 'either … or: hoặc … hoặc; either (cũng) dùng trong câu phủ định', '/ˈiːðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eit/eithe/either__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 23, 'ago', 'trước, cách đây', 'adverb', '[{"en":"I moved to this city five years ago.","vi":"Tôi chuyển đến thành phố này cách đây năm năm."},{"en":"She left the office a few minutes ago.","vi":"Cô ấy rời văn phòng vài phút trước."},{"en":"How long ago did you start learning English?","vi":"Bạn bắt đầu học tiếng Anh cách đây bao lâu rồi?"}]', '[{"phrase":"years ago"},{"phrase":"a long time ago"},{"phrase":"a few days ago"},{"phrase":"not long ago"}]', 'dùng với thì quá khứ đơn: two days ago', '/əˈɡəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ago/ago__/ago__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 24, 'per', 'mỗi', 'preposition', '[{"en":"The hotel costs eighty dollars per night.","vi":"Khách sạn có giá tám mươi đô la mỗi đêm."},{"en":"The speed limit here is thirty miles per hour.","vi":"Tốc độ tối đa ở đây là ba mươi dặm mỗi giờ."},{"en":"Tickets for the show cost ten dollars per person.","vi":"Vé xem buổi diễn có giá mười đô la mỗi người."}]', '[{"phrase":"per person"},{"phrase":"per hour"},{"phrase":"per night"},{"phrase":"per day"}]', NULL, '/pər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/per__/per__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 25, 'remain', 'vẫn (ở trạng thái); còn lại; ở lại', 'verb', '[{"en":"Please remain in your seats until the plane stops.","vi":"Xin quý khách vui lòng ngồi yên tại chỗ cho đến khi máy bay dừng hẳn."},{"en":"Many questions still remain about the accident.","vi":"Vẫn còn nhiều câu hỏi xoay quanh vụ tai nạn."},{"en":"The weather remained cold for the whole week.","vi":"Thời tiết vẫn lạnh suốt cả tuần."}]', '[{"phrase":"remain calm"},{"phrase":"remain the same"},{"phrase":"remain open"}]', NULL, '/rɪˈmeɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remai/remain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 26, 'top', 'đỉnh; phần trên cùng', 'noun', '[{"en":"It took us two hours to climb to the top of the hill.","vi":"Chúng tôi mất hai tiếng để leo lên đỉnh đồi."},{"en":"Write your name at the top of the page.","vi":"Hãy viết tên của bạn ở đầu trang."},{"en":"She put the heavy books on top of the box.","vi":"Cô ấy đặt mấy cuốn sách nặng lên trên cái hộp."}]', '[{"phrase":"the top of"},{"phrase":"on top of"},{"phrase":"reach the top"}]', NULL, '/tɑːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/top/top__/top__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 27, 'among', 'giữa (nhiều người, vật); trong số', 'preposition', '[{"en":"She felt happy and relaxed among her old friends.","vi":"Cô ấy thấy vui vẻ và thoải mái giữa những người bạn cũ."},{"en":"This song is very popular among young people.","vi":"Bài hát này rất được giới trẻ yêu thích."},{"en":"The money was shared among the three children.","vi":"Số tiền được chia cho ba đứa trẻ."}]', '[{"phrase":"among friends"},{"phrase":"popular among"},{"phrase":"among others"}]', 'among (giữa nhiều) ≠ between (giữa hai)', '/əˈmʌŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/amo/among/among__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 28, 'win', 'thắng; giành được', 'verb', '[{"en":"Our team won the game by two points.","vi":"Đội chúng tôi thắng trận đấu với cách biệt hai điểm."},{"en":"She won first prize in the singing contest.","vi":"Cô ấy giành giải nhất trong cuộc thi hát."},{"en":"Do you think we can win tomorrow''s match?","vi":"Bạn có nghĩ chúng ta có thể thắng trận đấu ngày mai không?"}]', '[{"phrase":"win a game"},{"phrase":"win a prize"},{"phrase":"win an award"},{"phrase":"win a match"}]', 'win – won – won', '/wɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/win/win__/win__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 29, 'color', 'màu sắc', 'noun', '[{"en":"What color would you like to paint the bedroom?","vi":"Bạn muốn sơn phòng ngủ màu gì?"},{"en":"The leaves change color in the fall.","vi":"Lá cây đổi màu vào mùa thu."},{"en":"This photo looks better in color than in black and white.","vi":"Bức ảnh này để màu trông đẹp hơn ảnh đen trắng."}]', '[{"phrase":"favorite color"},{"phrase":"bright colors"},{"phrase":"change color"}]', 'Anh: colour · Mỹ: color', '/ˈkʌlər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colou/colour__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-10', 30, 'involve', 'bao gồm, đòi hỏi; liên quan, tham gia vào', 'verb', '[{"en":"The job involves a lot of travel.","vi":"Công việc này đòi hỏi phải đi lại nhiều."},{"en":"Parents should be involved in their children''s education.","vi":"Cha mẹ nên tham gia vào việc học của con cái."},{"en":"I don''t want to get involved in their argument.","vi":"Tôi không muốn dính vào cuộc cãi vã của họ."}]', '[{"phrase":"be involved in"},{"phrase":"get involved"},{"phrase":"involve a lot of"}]', 'be/get involved in something', '/ɪnˈvɑːlv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/invol/involve__us_1.mp3', NULL, NULL);
